// Add features to a feature layer. This adaptor has no HTTP helpers,
// so call the ArcGIS REST API with util.request inside fn().
// baseUrl is your org's services host, e.g. https://services.arcgis.com/<orgId>/arcgis
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const features = state.data.submissions.map(s => ({
    geometry: { x: s.longitude, y: s.latitude, spatialReference: { wkid: 4326 } },
    attributes: { site_name: s.siteName, cases: s.caseCount, reported_on: s.date },
  }));
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Cholera_Cases/FeatureServer/0/addFeatures`,
    {
      // ArcGIS expects form-encoded params; `features` is a JSON string.
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ features: JSON.stringify(features), f: 'json', token }).toString(),
    }
  );
  return { ...state, data: res.body };
});

// Update features by OBJECTID.
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const features = state.data.updates.map(u => ({
    attributes: { OBJECTID: u.objectId, status: u.status, last_updated: u.date },
  }));
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Health_Facilities/FeatureServer/0/updateFeatures`,
    {
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ features: JSON.stringify(features), f: 'json', token }).toString(),
    }
  );
  return { ...state, data: res.body };
});

// Delete features by OBJECTID (or pass `where` instead).
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Cholera_Cases/FeatureServer/0/deleteFeatures`,
    {
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        objectIds: state.data.objectIds.join(','), // e.g. '1,2,3'
        f: 'json',
        token,
      }).toString(),
    }
  );
  return { ...state, data: res.body };
});

// Query features from a feature layer.
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const res = await util.request(
    'GET',
    `${baseUrl}/rest/services/Health_Facilities/FeatureServer/0/query`,
    {
      query: {
        where: `district = '${state.data.district}'`, // SQL-style filter; '1=1' for all
        outFields: '*', // or a comma-separated field list
        returnGeometry: true,
        f: 'json',
        token,
      },
    }
  );
  return { ...state, data: res.body.features };
});

// Geocode a single-line address.
fn(async state => {
  const res = await util.request(
    'GET',
    'https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates',
    {
      query: {
        SingleLine: state.data.address, // e.g. 'Kenyatta National Hospital, Nairobi'
        outFields: 'Match_addr,Addr_type',
        f: 'json',
        token: state.configuration.token,
      },
    }
  );
  // Best match first: candidates[0].location has x (lon) and y (lat).
  return { ...state, data: res.body.candidates };
});

// Generate an access token and keep it on state for later steps.
fn(async state => {
  const { username, password } = state.configuration;
  const res = await util.request('POST', 'https://www.arcgis.com/sharing/rest/generateToken', {
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      username,
      password,
      referer: 'https://app.openfn.org',
      expiration: '60', // minutes
      f: 'json',
    }).toString(),
  });
  return { ...state, token: res.body.token };
});

asana.code:
// Move a task into a section of a project.
request(`/sections/${$.data.sectionGid}/addTask`, {
  method: 'POST',
  body: {
    data: {
      // The task to add to the section.
      task: $.data.taskGid,
    },
  },
});

// Add a comment / story to a task.
createTaskStory(
  // 1) The task's globally unique id.
  $.data.taskGid,
  {
    // 2) The comment body (HTML supported when html_text is used).
    text: 'Status update: imported from the upstream system.',
  }
);

// Duplicate an existing task.
request(`/tasks/${$.data.taskGid}/duplicate`, {
  method: 'POST',
  body: {
    data: {
      // Name for the new task.
      name: `Copy of ${$.data.taskName}`,
      // Comma-separated list of fields to copy over.
      include: 'assignee,notes,projects,subtasks,tags',
    },
  },
});

// Create a new project in a workspace.
request('/projects', {
  method: 'POST',
  body: {
    data: {
      name: 'Measles vaccination campaign 2026',
      notes: 'Tracks outreach, cold chain and reporting tasks.',
      workspace: $.configuration.workspaceGid,
      // Required for organisation workspaces: the owning team gid.
      team: $.data.teamGid,
    },
  },
});

// Create a new section within a project.
request(`/projects/${$.data.projectGid}/sections`, {
  method: 'POST',
  body: {
    data: {
      name: 'Awaiting lab results',
    },
  },
});

// Create a new task.
createTask({
  // The task's title.
  name: 'Follow up with patient',
  // Long-form description (optional).
  notes: `Imported from upstream system on ${new Date().toISOString()}`,
  // Workspace gid this task lives in.
  workspace: $.configuration.workspaceGid,
  // Optional: place the task into a project on creation.
  projects: [$.data.projectGid],
  // Optional: assign to a user gid.
  assignee: $.data.assigneeGid,
  // Optional ISO date string.
  due_on: '2026-06-01',
});

// Create a task from a task template.
request(`/task_templates/${$.data.taskTemplateGid}/instantiateTask`, {
  method: 'POST',
  body: {
    data: {
      // Name of the new task.
      name: `Home visit: ${$.data.householdId}`,
    },
  },
});

// Update properties on an existing task.
updateTask(
  // 1) Task gid.
  $.data.taskGid,
  // 2) Fields to change.
  {
    name: 'Updated task title',
    completed: true,
    notes: 'Closed after upstream sync.',
  }
);

// Make an arbitrary request against the Asana API.
// Path is relative to the Asana base URL.
request('/workspaces', {
  method: 'GET',
  query: { limit: 10 },
});

// List tasks in a project.
getTasks(
  // 1) Project gid.
  $.data.projectGid,
  // 2) Query params.
  {
    // Fields to return per task.
    opt_fields: 'name,notes,assignee,completed,due_on',
    // Cap the result size.
    limit: 100,
  }
);

// Find projects in a workspace whose name matches a search term.
request(`/workspaces/${$.configuration.workspaceGid}/typeahead`, {
  query: {
    resource_type: 'project',
    query: $.data.projectName,
    count: 5,
  },
});

// List the sections in a project, then keep the one matching a name.
request(`/projects/${$.data.projectGid}/sections`, {
  query: { opt_fields: 'name' },
});

fn(state => {
  state.data = state.data.find(section => section.name === 'Awaiting lab results');
  return state;
});

// List the stories on a task, then keep only the comments.
request(`/tasks/${$.data.taskGid}/stories`, {
  query: { opt_fields: 'type,text,created_by.name,created_at' },
});

fn(state => {
  state.data = state.data.filter(story => story.type === 'comment');
  return state;
});

// Search tasks across a workspace using Asana's typeahead/search API.
// Note: this endpoint requires a premium Asana plan.
searchTask(
  // 1) The search term (matches task name).
  $.data.searchTerm,
  // 2) Query params (assignee, completed, etc).
  {
    'assignee.any': $.data.assigneeGid,
    completed: false,
  }
);

// Find a user in a workspace by email (or user gid).
request(
  `/workspaces/${$.configuration.workspaceGid}/users/${$.data.email}`,
  {
    query: { opt_fields: 'name,email' },
  }
);

aws-s3.code:
// Archive the incoming payload to S3 as JSON.
put({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  key: `submissions/${new Date().toISOString().slice(0, 10)}/${$.data.id}.json`,
  body: JSON.stringify($.data),
  contentType: 'application/json',
});

// Build a CSV from rows and upload it to S3.
put({
  key: `exports/payments-${new Date().toISOString().slice(0, 10)}.csv`,
  body: [
    'beneficiary_id,name,amount,currency',
    ...$.data.payments.map(p => `${p.beneficiaryId},${p.name},${p.amount},${p.currency}`),
  ].join('\n'),
  contentType: 'text/csv',
});

// Upload a sensitive file with server-side encryption.
put({
  key: `lab-results/${$.data.facilityCode}/${$.data.fileName}`,
  body: Buffer.from($.data.fileBase64, 'base64'), // decode an attachment
  contentType: $.data.mimeType, // e.g. 'application/pdf'
  serverSideEncryption: 'AES256', // or 'aws:kms'
});

// Write one object per record.
each(
  $.data.patients,
  put({
    key: `patients/${$.data.patientId}.json`,
    body: JSON.stringify($.data),
    contentType: 'application/json',
  })
);

// List objects under a prefix.
list({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  prefix: 'incoming/2026-11/',
  maxKeys: 100,
});

// List a drop folder, then keep files newer than the last run.
list({ prefix: 'incoming/' });
fn(state => {
  const since = new Date(state.lastRunAt || 0);
  state.newFiles = state.data.filter(obj => new Date(obj.LastModified) > since);
  state.lastRunAt = new Date().toISOString();
  return state;
});

// Download and parse a JSON file.
get({
  key: `config/facility-mappings.json`,
});

// Download a file. Non-JSON content (CSV, PDF, image) is returned
// base64-encoded, with its contentType and contentLength.
get({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  key: $.data.key, // e.g. 'incoming/2026-11/enrolment.csv'
});

azure-storage.code:
// Archive today's form submissions as a JSON blob.
uploadBlob(
  // 1) Blob name; slashes act as virtual folders.
  `submissions/${new Date().toISOString().slice(0, 10)}.json`,
  // 2) Content; objects are JSON-stringified for you.
  $.data.submissions,
  // 3) Azure BlockBlobUploadOptions.
  { blobHTTPHeaders: { blobContentType: 'application/json' } },
  // 4) Adaptor options.
  { createContainer: true }
);

// Upload a monthly indicators CSV for the BI team.
uploadBlob(
  `exports/indicators-${$.data.period}.csv`,
  $.data.csv, // a CSV string built in an earlier step
  { blobHTTPHeaders: { blobContentType: 'text/csv' } },
  { overwrite: true } // replace the file if this period is re-run
);

// Write a payment reconciliation file to the 'finance' container.
uploadBlob(
  `reconciliation/${$.data.batchId}.json`,
  {
    batchId: $.data.batchId,
    totalPaid: $.data.totalPaid,
    failedPayments: $.data.failed,
  },
  { blobHTTPHeaders: { blobContentType: 'application/json' } },
  {
    containerName: 'finance', // overrides state.configuration.containerName
    overwrite: true,
  }
);

// Store each beneficiary record as its own JSON file.
each(
  $.data.beneficiaries,
  uploadBlob(
    // Inside each(), $.data is the current record.
    `beneficiaries/${$.data.id}.json`,
    $.data,
    { blobHTTPHeaders: { blobContentType: 'application/json' } },
    { overwrite: true }
  )
);

// Download a facility mapping table and parse it as JSON.
// The result is in state.data.content.
downloadBlob('config/facility-mapping.json', {
  downloadAs: 'json', // or 'string' (default)
});

// Download a CSV dropped by a partner system.
downloadBlob(`incoming/${$.data.fileName}`, {
  downloadAs: 'string',
  containerName: 'partner-uploads', // optional; defaults to the credential's container
});

// Check when the latest export was last written.
// The result is in state.data.properties (lastModified, contentLength, etc.).
getBlobProperties('exports/latest.csv');

beyonic.code:
// Pay a cash transfer to a beneficiary's mobile money wallet.
// The API response is added to state.references.
createPayment({
  phonenumber: $.data.phone, // international format, e.g. '+256700000000'
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  amount: String($.data.amount), // sent as a string, e.g. '50000'
  currency: 'UGX',
  description: 'Monthly cash transfer',
  payment_type: 'money',
  // Your own ids travel with the payment and come back in callbacks.
  metadata: { beneficiaryId: $.data.beneficiaryId, cycle: $.data.cycle },
});

// Pay a community health worker stipend and get status updates via callback.
createPayment({
  phonenumber: $.data.phone,
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  amount: '150000',
  currency: 'UGX',
  description: `CHW stipend ${$.data.month}`,
  callback_url: 'https://app.openfn.org/i/<your-webhook-id>',
  send_sms_message: true, // notify the recipient by SMS
  metadata: { chwId: $.data.chwId },
});

// Register a beneficiary as a Beyonic contact.
createContact({
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  phone_number: $.data.phone, // required, e.g. '+256700000000'
  email: $.data.email,
  type: 'beneficiary',
  metadata: { householdId: $.data.householdId },
});

// Request a savings-group or insurance contribution from a member.
createCollectionRequest({
  phonenumber: $.data.phone, // required
  amount: String($.data.amount), // required, e.g. '3000'
  currency: 'UGX', // required
  reason: 'Community health insurance premium',
  send_instructions: true, // text the payer instructions on how to pay
  success_message: 'Thank you, your premium has been received.',
  metadata: { memberId: $.data.memberId },
});

