browserless.code:
// Render HTML to a PDF. state.data will hold the PDF as a base64 string,
// ready to attach to an email or upload to a file store.
createPDF({
  html: `
    <h1>Payment Receipt</h1>
    <p>Beneficiary: ${$.data.beneficiaryName}</p>
    <p>Amount: ${$.data.amount} ${$.data.currency}</p>
    <p>Date: ${$.data.paidOn}</p>
  `,
  options: {
    format: 'A4',
    printBackground: true,
  },
});

// Print a web page to PDF.
createPDF({
  url: $.data.reportUrl, // e.g. a public dashboard link
  options: { format: 'A4', landscape: true },
  // Wait until the page's charts have finished loading.
  gotoOptions: { waitUntil: 'networkidle2', timeout: 60000 },
});

// Capture a screenshot. Paths are relative to the Browserless baseUrl;
// the token is added for you.
request('POST', 'screenshot', {
  body: {
    url: $.data.dashboardUrl,
    options: { fullPage: true, type: 'png' },
    gotoOptions: { waitUntil: 'networkidle2' },
  },
  parseAs: 'base64', // state.data becomes a base64 image
});

// Scrape elements from a rendered page.
request('POST', 'scrape', {
  body: {
    url: 'https://www.example.org/market-prices',
    elements: [
      { selector: 'table.prices tr' }, // one entry per CSS selector
      { selector: 'h1' },
    ],
    gotoOptions: { waitUntil: 'networkidle2' },
  },
});

// Get the HTML of a page after JavaScript has run.
request('POST', 'content', {
  body: {
    url: $.data.pageUrl,
    gotoOptions: { waitUntil: 'networkidle2', timeout: 30000 },
  },
  parseAs: 'text',
});

cartodb.code:
// Insert a row into a CARTO table.
addRow(
  // 1) Table name.
  'case_reports',
  // 2) Column values.
  {
    case_id: $.data.caseId,
    disease: $.data.disease,
    district: $.data.district,
    reported_on: $.data.reportedOn,
  }
);

// Insert a geolocated row (PostGIS point) with SQL.
// `sql` takes a function that returns the query string.
sql(
  state => `INSERT INTO health_facilities (name, facility_type, the_geom)
  VALUES (
    '${state.data.name}',
    '${state.data.type}',
    ST_SetSRID(ST_MakePoint(${state.data.longitude}, ${state.data.latitude}), 4326)
  )`
);

// Update a row's status with SQL.
sql(
  state => `UPDATE water_points
  SET status = '${state.data.status}', last_visit = '${state.data.visitDate}'
  WHERE water_point_id = '${state.data.waterPointId}'`
);

// Find facilities within 5 km of a point.
sql(
  state => `SELECT name, facility_type
  FROM health_facilities
  WHERE ST_DWithin(
    the_geom::geography,
    ST_SetSRID(ST_MakePoint(${state.data.longitude}, ${state.data.latitude}), 4326)::geography,
    5000
  )`
);

// Count case reports per district.
sql(
  state => `SELECT district, COUNT(*) AS cases
  FROM case_reports
  WHERE reported_on >= '${state.data.since}'
  GROUP BY district
  ORDER BY cases DESC`
);

chatgpt.code:
// Ask a question about an image via Chat Completions.
// Override `messages` to attach an image part alongside the text.
prompt(null, {
  model: 'gpt-4o-mini',
  messages: [
    {
      role: 'user',
      content: [
        { type: 'text', text: 'Describe what is happening in this image.' },
        { type: 'image_url', image_url: { url: $.data.imageUrl } },
      ],
    },
  ],
});

// Analyze an image via the Responses API.
// Override `input` to attach an image alongside the text prompt.
deepResearch(null, {
  model: 'gpt-4o',
  // No web search needed for pure image analysis.
  tools: [],
  input: [
    {
      role: 'user',
      content: [
        { type: 'input_text', text: 'Describe what is happening in this image.' },
        { type: 'input_image', image_url: $.data.imageUrl },
      ],
    },
  ],
});

// Analyze a block of text via the Responses API.
deepResearch(
  `Analyze the following text. Return the key themes, tone and any action items.\n\nTEXT:\n${$.data.text}`,
  {
    model: 'gpt-4o',
    // No web search needed; disable the default tool.
    tools: [],
  }
);

// Return a sentiment label + score for a block of text.
prompt(
  `Rate the sentiment of the text below. Reply as JSON:\n{ "label": "positive" | "neutral" | "negative", "score": number between -1 and 1 }\n\nTEXT:\n${$.data.text}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0,
    // Force the model to emit valid JSON.
    response_format: { type: 'json_object' },
  }
);

// Flag potentially harmful text.
// Note: this adaptor doesn't wrap OpenAI's /moderations endpoint, so this
// uses a chat model as a classifier. It is not a drop-in replacement.
prompt(
  `Classify the text below for harmful content. Reply as JSON:\n{ "flagged": boolean, "categories": string[] }\nUse only these categories: harassment, hate, self-harm, sexual, violence.\n\nTEXT:\n${$.data.text}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0,
    // Force the model to emit valid JSON.
    response_format: { type: 'json_object' },
  }
);

// Classify text into one of the supplied categories.
const categories = ['billing', 'support', 'sales', 'other'];

prompt(
  `Pick the single best category for the message below. Reply with the\ncategory string only, nothing else.\n\nCATEGORIES: ${categories.join(', ')}\n\nMESSAGE:\n${$.data.message}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0,
  }
);

// Send a chat turn via the Responses API, with tools enabled.
// Default tool is web_search_preview; override `tools` to use file_search, MCP, etc.
deepResearch(
  $.data.userMessage,
  {
    model: 'gpt-4o',
    tools: [{ type: 'web_search_preview' }],
  }
);

// Multi-turn chat via Chat Completions. Provide the full message history.
// `prompt`'s first arg is ignored when `messages` is overridden.
prompt(null, {
  model: 'gpt-4o-mini',
  messages: [
    { role: 'system', content: 'You are a concise assistant.' },
    ...($.state.history || []),
    { role: 'user', content: $.data.userMessage },
  ],
  temperature: 0.5,
});

// Turn a text message into spoken audio.
// Note: /audio/speech isn't wrapped by this adaptor, so this uses an
// audio-capable chat model. The base64 audio lands on
// state.data.choices[0].message.audio.data.
prompt(
  `Read the following message aloud, word for word:\n\n${$.data.text}`,
  {
    model: 'gpt-4o-audio-preview',
    // Ask for a text transcript plus spoken audio.
    modalities: ['text', 'audio'],
    audio: { voice: 'alloy', format: 'mp3' },
  }
);

// Not supported by this adaptor.
// prompt() calls Chat Completions and deepResearch() calls the Responses API;
// neither can return embedding vectors from POST /embeddings.
// Workaround: call the endpoint from the HTTP adaptor in a separate step:
// post('https://api.openai.com/v1/embeddings', {
//   model: 'text-embedding-3-small',
//   input: $.data.text,
// }, {
//   headers: { Authorization: `Bearer ${$.configuration.apiKey}` },
// });

// Edit an existing image with a text instruction, via the Responses API
// image_generation tool (this adaptor doesn't wrap /images/edits).
// The base64 result is in the `image_generation_call` item of state.data.output.
deepResearch(null, {
  model: 'gpt-4o',
  tools: [{ type: 'image_generation' }],
  input: [
    {
      role: 'user',
      content: [
        { type: 'input_text', text: 'Replace the background with a plain white wall.' },
        { type: 'input_image', image_url: $.data.imageUrl },
      ],
    },
  ],
});

// Transcribe an audio recording.
// Note: /audio/transcriptions (Whisper) isn't wrapped by this adaptor, so this
// sends the audio to an audio-capable chat model instead. Video files are not
// supported this way; extract the audio track first.
prompt(null, {
  model: 'gpt-4o-audio-preview',
  messages: [
    {
      role: 'user',
      content: [
        { type: 'text', text: 'Transcribe this recording word for word.' },
        // Base64-encoded audio, e.g. from an upstream step.
        { type: 'input_audio', input_audio: { data: $.data.audioBase64, format: 'mp3' } },
      ],
    },
  ],
});

// Translate spoken audio into English text.
// Note: /audio/translations isn't wrapped by this adaptor, so this sends the
// audio to an audio-capable chat model instead.
prompt(null, {
  model: 'gpt-4o-audio-preview',
  messages: [
    {
      role: 'user',
      content: [
        { type: 'text', text: 'Translate this recording into English. Return the translation only.' },
        // Base64-encoded audio, e.g. a voice note from a community health worker.
        { type: 'input_audio', input_audio: { data: $.data.audioBase64, format: 'wav' } },
      ],
    },
  ],
});

// Not supported by this adaptor.
// Sora video generation needs OpenAI's video endpoints, which neither
// prompt() (Chat Completions) nor deepResearch() (Responses API) can call.
// Workaround: use the HTTP adaptor in a separate step, with your OpenAI key
// in an Authorization: Bearer header, and save the returned job id.

// Extract structured fields via the Responses API, constrained to a JSON schema.
deepResearch(
  `Extract the contact details from the message below.\n\nMESSAGE:\n${$.data.message}`,
  {
    model: 'gpt-4o',
    tools: [],
    text: {
      format: {
        type: 'json_schema',
        name: 'contact',
        schema: {
          type: 'object',
          properties: {
            name:  { type: 'string' },
            email: { type: 'string' },
            phone: { type: 'string' },
          },
          required: ['name'],
          additionalProperties: false,
        },
      },
    },
  }
);

// Extract structured fields from unstructured text via Chat Completions.
// The model is constrained to a JSON schema; result lands on state.data.
prompt(
  `Extract the contact details from the message below.\n\nMESSAGE:\n${$.data.message}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0,
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'contact',
        schema: {
          type: 'object',
          properties: {
            name:  { type: 'string' },
            email: { type: 'string' },
            phone: { type: 'string' },
          },
          required: ['name'],
          additionalProperties: false,
        },
      },
    },
  }
);

// Generate an image via the Responses API image_generation tool.
// The base64 image is in the `image_generation_call` item of state.data.output.
deepResearch(
  `A friendly, flat-style illustration of a nurse vaccinating a child at a rural clinic. ${$.data.extraDetails || ''}`,
  {
    model: 'gpt-4o',
    // Swap the default web search tool for image generation.
    tools: [{ type: 'image_generation' }],
  }
);

// Send a free-form prompt. Note: this adaptor calls Chat Completions under
// the hood, not the legacy text-completions endpoint.
prompt(
  `What are three risks to watch for in the following plan?\n\n${$.data.plan}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0.5,
  }
);

// Summarize a chunk of text.
prompt(
  `Summarize the text below in 3 short bullet points.\n\nTEXT:\n${$.data.text}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0.2,
  }
);

// Draft an email body for use in a later send step.
prompt(
  `Write a friendly email to ${$.data.recipientName} confirming their\nappointment on ${$.data.appointmentDate}. Sign it from \"OpenFn Team\".`,
  {
    model: 'gpt-4o-mini',
    temperature: 0.7,
  }
);

// Not supported by this adaptor: there is no generic request helper.
// prompt() calls POST /chat/completions and deepResearch() calls POST /responses;
// any other parameters you pass are forwarded in the request body.
// For other endpoints, use the HTTP adaptor with an Authorization: Bearer header.
deepResearch($.data.input, {
  model: 'gpt-4o',
  tools: [],
  // Any Responses API body field can be set here.
  metadata: { source: 'openfn' },
});

// Not supported by this adaptor: GET /conversations/{conversation_id} isn't wrapped.
// Closest option: continue an existing conversation by id via the Responses API.
deepResearch($.data.userMessage, {
  model: 'gpt-4o',
  tools: [],
  // The conv_* id of the conversation to append to.
  conversation: $.data.conversationId,
});

// Not supported by this adaptor.
// GET /files (list) and GET /files/{file_id} aren't wrapped, and there is no
// way to upload a file either, so files can't be found or created here.
// Workaround: use the HTTP adaptor in a separate step to call GET /files with
// an Authorization: Bearer header, then filter the results by `filename`.

// Not supported by this adaptor: GET /responses/{response_id} isn't wrapped.
// Closest option: chain onto a stored response by id, e.g. to ask the model
// to restate what it answered for an audit trail.
deepResearch('Repeat your previous answer exactly.', {
  model: 'gpt-4o',
  tools: [],
  // The resp_* id of the stored response.
  previous_response_id: $.data.responseId,
});

// Not supported by this adaptor.
// Checking a Sora job's status needs OpenAI's video endpoints, which neither
// prompt() nor deepResearch() can call.
// Workaround: use the HTTP adaptor in a separate step, with your OpenAI key
// in an Authorization: Bearer header.

// Rank documents by how well they match a query.
// Note: this adaptor can't call /embeddings, so a chat model does the ranking.
const documents = ['mouse', 'cat', 'buffalo', 'blue whale'];

prompt(
  `Rank these documents by semantic similarity to the query. Reply as JSON:\n{ "results": [{ "document": string, "score": number between 0 and 1 }] }\n\nQUERY: ${$.data.query}\nDOCUMENTS: ${JSON.stringify(documents)}`,
  {
    model: 'gpt-4o-mini',
    temperature: 0,
    response_format: { type: 'json_object' },
  }
);

