// Register a new patient under an existing household/place.
post('/api/v1/person', {
  name: $.data.fullName,
  type: 'person', // or a configured contact_type id, e.g. 'patient'
  parent: $.data.householdId, // uuid of the parent place
  date_of_birth: $.data.dateOfBirth, // 'YYYY-MM-DD'
  sex: $.data.sex, // 'female' | 'male'
  phone: $.data.phone, // e.g. '+254712345678'
});

// Create a household under a community health worker's area.
post('/api/v1/place', {
  name: `${$.data.familyName} Household`,
  type: 'clinic', // household level in the default hierarchy
  parent: $.data.chwAreaId, // uuid of the parent place
  place_id: $.data.externalHouseholdId, // optional external id
});

// Submit a JSON report against a configured form.
post('/api/v2/records', {
  _meta: {
    form: 'P', // form code, e.g. pregnancy registration
    from: $.data.chwPhone, // reporting phone number
    reported_date: Date.now(),
  },
  patient_id: $.data.patientId,
  lmp: $.data.weeksSinceLmp, // form fields: strings or numbers only
});

// Update a person's record. Use request() because put() takes no body.
request(
  // 1) HTTP method.
  'PUT',
  // 2) Path to the person.
  `/api/v1/person/${$.data.personId}`,
  // 3) Updated fields (type, parent and contact_type are read-only).
  {
    _id: $.data.personId,
    _rev: $.data.rev, // current revision, from a prior get
    name: $.data.fullName,
    phone: $.data.phone,
  }
);

// Create an offline user for a new community health worker.
post('/api/v3/users', {
  username: $.data.username, // e.g. 'chw_amina'
  fullname: $.data.fullName,
  roles: ['chw'],
  place: $.data.chwAreaId, // place the CHW is assigned to
  contact: $.data.personId, // their person record
  phone: $.data.phone,
  token_login: true, // send a magic login link instead of a password
});

// Export reports for given forms within a date range.
get('/api/v2/export/reports', {
  query: {
    filters: {
      forms: { selected: [{ code: 'pregnancy' }, { code: 'delivery' }] },
      // Epoch milliseconds.
      date: { from: $.data.fromMs, to: $.data.toMs },
    },
  },
});

// Export contacts that match a search term.
get('/api/v2/export/contacts', {
  query: {
    filters: { search: $.data.searchTerm },
  },
});

// List persons of one contact type (paginated with a cursor).
get('/api/v1/person', {
  query: {
    type: 'person', // contact_type id to fetch
    limit: 100,
    cursor: $.data.nextCursor, // omit for the first page
  },
});

// Find contacts by phone number (e.g. from an incoming SMS).
get('/api/v1/contacts-by-phone', {
  query: { phone: $.data.phone },
});

// Fetch target documents (CHW performance indicators).
get('/api/v1/target', {
  query: { limit: 100 },
});

