commcare.code:
// Create or update a case by external id (Case API v2).
// request() paths are relative to the host URL, so include /a/<domain>/.
request(
  // 1) HTTP method.
  'PUT',
  // 2) Path, with the external id from the incoming record.
  `/a/${$.configuration.domain}/api/case/v2/ext/${$.data.externalId}/`,
  // 3) Body: a CaseV2Update.
  {
    case_type: 'patient',
    case_name: $.data.fullName,
    owner_id: $.data.ownerId,
    properties: {
      date_of_birth: $.data.dob,
      phone_number: $.data.phone,
      village: $.data.village,
    },
  }
);

// Create or update several cases at once (Case API v2 bulk upsert on external_id).
request(
  'PUT',
  `/a/${$.configuration.domain}/api/case/v2/`,
  $.data.patients.map(p => ({
    case_type: 'patient',
    external_id: p.nationalId,
    case_name: p.name,
    owner_id: p.ownerId,
    // Required in bulk requests: true creates, false updates.
    create: !p.caseId,
    properties: { district: p.district, enrollment_date: p.enrolledOn },
  }))
);

// Bulk import case data. Rows are converted to XLS and sent to the case importer.
bulk(
  // 1) Upload type.
  'case-data',
  // 2) One object per row; keys become column headers.
  $.data.households.map(h => ({
    external_id: h.householdId,
    name: h.headOfHousehold,
    phone: h.phone,
    village: h.village,
  })),
  // 3) Importer options.
  {
    case_type: 'household',
    search_field: 'external_id',
    create_new_cases: 'on',
  }
);

// Submit a form (as XML) to the app set in configuration.appId.
submit({
  '@': {
    xmlns: 'http://openrosa.org/formdesigner/5B2A6C1F-3D4E-4F9A-8B7C-2E1D0A9F6B3C',
  },
  beneficiary_name: $.data.name,
  phone_number: $.data.phone,
  registration_date: $.data.registeredOn,
});

// Create a mobile worker. post() paths are relative to /a/<domain>/api/v0.5/.
post('user/', {
  username: $.data.username,
  // Generate or pass a temporary password; never hardcode real credentials.
  password: $.data.tempPassword,
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  default_phone_number: $.data.phone,
  language: 'en',
  locations: [$.data.locationId],
});

// Upload lookup table rows.
bulk(
  'lookup-table',
  {
    // Table definition.
    types: [
      {
        'DELETE(Y/N)': 'N',
        table_id: 'facilities',
        'is_global?': 'yes',
        'field 1': 'code',
        'field 2': 'name',
      },
    ],
    // Table rows, keyed by table_id.
    facilities: $.data.facilities.map(f => ({
      UID: '',
      'DELETE(Y/N)': 'N',
      'field:code': f.code,
      'field:name': f.name,
    })),
  },
  // Append/update rather than replace the whole table.
  { replace: false }
);

// List cases. get() paths are relative to /a/<domain>/api/v0.5/ and auto-paginate.
get('case/', {
  type: 'patient',
  server_date_modified_start: $.data.since, // e.g. '2026-10-01'
  closed: false,
});

// List form submissions for one form, received since a date.
get('form/', {
  xmlns: 'http://openrosa.org/formdesigner/5B2A6C1F-3D4E-4F9A-8B7C-2E1D0A9F6B3C',
  received_on_start: '2026-10-01',
  order_by: 'received_on',
});

// Get a case by external id (Case API v2).
request(
  'GET',
  `/a/${$.configuration.domain}/api/case/v2/ext/${$.data.externalId}/`
);

