// Register a person and enroll them in a tracker program.
create('trackedEntities', {
  orgUnit: $.data.facilityId, // e.g. 'DiszpKrYNg8'
  trackedEntityType: 'nEenWmSyUEp', // Person
  attributes: [
    { attribute: 'w75KJ2mc4zz', value: $.data.firstName }, // First name
    { attribute: 'zDhUuAYrxNC', value: $.data.lastName }, // Last name
  ],
  enrollments: [
    {
      program: 'IpHINAT79UW', // Child Programme
      orgUnit: $.data.facilityId,
      enrolledAt: $.data.registrationDate,
      occurredAt: $.data.registrationDate,
    },
  ],
});

// Enroll an existing tracked entity in a program.
create('enrollments', {
  trackedEntity: $.data.trackedEntityId,
  program: 'IpHINAT79UW', // Child Programme
  orgUnit: $.data.facilityId,
  enrolledAt: $.data.enrollmentDate,
  occurredAt: $.data.enrollmentDate,
  status: 'ACTIVE',
});

// Record a visit (program stage event) for an enrolled person.
create('events', {
  program: 'IpHINAT79UW', // Child Programme
  programStage: 'A03MvHHogjR', // Birth stage
  enrollment: $.data.enrollmentId,
  trackedEntity: $.data.trackedEntityId,
  orgUnit: $.data.facilityId,
  occurredAt: $.data.visitDate,
  status: 'COMPLETED',
  dataValues: [
    { dataElement: 'UXz7xuGCEhU', value: $.data.weightGrams }, // Weight (g)
    { dataElement: 'bx6fsa0t90x', value: $.data.bcgGiven }, // BCG dose
  ],
});

// Submit a monthly aggregate report for a facility.
create('dataValueSets', {
  dataSet: 'pBOMPrpg1QX', // the reporting data set
  period: $.data.period, // e.g. '202610' (monthly)
  orgUnit: $.data.facilityId,
  completeDate: new Date().toISOString().slice(0, 10),
  dataValues: $.data.indicators.map(i => ({
    dataElement: i.dataElementId,
    categoryOptionCombo: i.categoryOptionComboId, // optional
    value: String(i.value),
  })),
});

// Create or update a tracked entity by its UID.
upsert(
  // 1) Resource type (sent to the tracker API).
  'trackedEntities',
  // 2) Query (not used by tracker resources; matching is by UID).
  {},
  // 3) The tracked entity payload.
  {
    trackedEntity: $.data.trackedEntityId,
    orgUnit: $.data.facilityId,
    trackedEntityType: 'nEenWmSyUEp', // Person
    attributes: [
      { attribute: 'w75KJ2mc4zz', value: $.data.firstName },
      { attribute: 'zDhUuAYrxNC', value: $.data.lastName },
    ],
  }
);

// Create or update a facility (organisation unit) matched by its code.
upsert(
  // 1) Metadata resource type.
  'organisationUnits',
  // 2) Query that uniquely identifies the record.
  { filter: `code:eq:${$.data.facilityCode}` },
  // 3) Full organisation unit payload.
  {
    code: $.data.facilityCode,
    name: $.data.facilityName,
    shortName: $.data.facilityName.slice(0, 50),
    openingDate: $.data.openingDate, // e.g. '2020-01-01'
    parent: { id: $.data.districtId },
  }
);

// Update a program. PUT replaces the object, so send all required fields.
update(
  // 1) Resource type.
  'programs',
  // 2) Program UID.
  $.data.programId,
  // 3) The full program object.
  {
    name: 'Malaria Case Surveillance',
    shortName: 'Malaria CS',
    programType: 'WITHOUT_REGISTRATION',
  }
);

// Find people in a program by an attribute (e.g. national ID).
get('tracker/trackedEntities', {
  program: 'IpHINAT79UW', // Child Programme
  orgUnits: $.data.districtId,
  orgUnitMode: 'DESCENDANTS', // search the district and everything below it
  filter: `lZGmxYbs97q:eq:${$.data.uniqueId}`, // attribute UID:operator:value
  fields: 'trackedEntity,orgUnit,attributes[attribute,value],enrollments[enrollment,status]',
});

// Fetch one tracked entity, including its enrollments and events.
get(`tracker/trackedEntities/${$.data.trackedEntityId}`, {
  program: 'IpHINAT79UW',
  fields: '*,enrollments[*,events[*]]',
});

// Export events changed since the last sync.
get('tracker/events', {
  program: 'eBAyeGv0exc', // Inpatient morbidity and mortality
  orgUnit: $.data.districtId,
  orgUnitMode: 'DESCENDANTS',
  updatedAfter: $.lastSyncTime || '2026-01-01',
  pageSize: 200,
  page: 1,
});

// List active enrollments in a program.
get('tracker/enrollments', {
  program: 'IpHINAT79UW',
  orgUnits: $.data.districtId,
  orgUnitMode: 'DESCENDANTS',
  status: 'ACTIVE',
  fields: 'enrollment,trackedEntity,enrolledAt,status',
});

// Export aggregate data values for a data set and period.
get('dataValueSets', {
  dataSet: 'pBOMPrpg1QX',
  orgUnit: $.data.facilityId,
  period: $.data.period, // e.g. '202610'
  children: true, // include child org units
});

// List all organisation units at level 4 (facilities).
get('organisationUnits', {
  level: 4,
  fields: 'id,code,name,parent[id,name],geometry',
  paging: false,
});

// Query analytics: indicator values by district for the last 12 months.
get('analytics', {
  dimension: [
    `dx:${$.data.indicatorId}`, // data element or indicator UID
    'pe:LAST_12_MONTHS',
    'ou:LEVEL-2', // districts
  ],
  displayProperty: 'NAME',
});

// List programs and their stages.
get('programs', {
  fields: 'id,name,programType,programStages[id,name]',
  paging: false,
});

