  filter: `my_externalid eq '${$.data.externalId}'`,
});

// Look up an Invoice by name or number.
query({
  entityName: 'invoices',
  filter: `name eq '${$.data.invoiceName}'`,
});

// Look up a Lead by email.
query({
  entityName: 'leads',
  filter: `emailaddress1 eq '${$.data.email}'`,
});

// Look up an Opportunity by name.
query({
  entityName: 'opportunities',
  filter: `name eq '${$.data.opportunityName}'`,
});

// Find an Account by name, or create it if missing.
// 1) Look for an existing record. query() puts the raw response on state.response.body.
query({
  entityName: 'accounts',
  query: {
    // OData $filter; quote string values with single quotes.
    filter: `name eq '${$.data.name}'`,
    fields: ['accountid', 'name'],
  },
});

// 2) Nothing matched? Create it.
fnIf(
  state => JSON.parse(state.response.body).value.length === 0,
