// Find a Sales Order by name, or create it if missing.
// 1) Look for an existing record. query() puts the raw response on state.response.body.
query({
  entityName: 'salesorders',
  query: {
    // OData $filter; quote string values with single quotes.
    filter: `name eq '${$.data.orderName}'`,
    fields: ['salesorderid', 'name'],
  },
});

// 2) Nothing matched? Create it.
fnIf(
