fhir-4.code:
// Create a Patient from an incoming registration.
create(
  b.patient({
    identifier: [{ system: 'urn:example:national-id', value: $.data.nationalId }],
    name: { family: $.data.lastName, given: $.data.firstName, use: 'official' },
    gender: $.data.gender, // 'male' | 'female' | 'other' | 'unknown'
    birthDate: $.data.dateOfBirth, // 'YYYY-MM-DD'
  })
);

// Create an Observation (any resource with a resourceType can be passed).
create({
  resourceType: 'Observation',
  status: 'final',
  code: {
    coding: [{ system: 'http://loinc.org', code: '70569-9', display: 'Plasmodium sp Ag [Presence] in Blood by Rapid immunoassay' }],
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  effectiveDateTime: $.data.testedAt,
  valueCodeableConcept: { text: $.data.result }, // e.g. 'Positive'
});

// Create an outpatient Encounter.
create({
  resourceType: 'Encounter',
  status: 'finished',
  class: { system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode', code: 'AMB' },
  subject: { reference: `Patient/${$.data.patientId}` },
  serviceProvider: { reference: `Organization/${$.data.facilityId}` },
  period: { start: $.data.visitStart, end: $.data.visitEnd },
});

// Update a Patient. Creates it (201) if the id doesn't exist yet.
update(
  // 1) Resource reference, Type/id.
  `Patient/${$.data.patientId}`,
  // 2) The full new version of the resource.
  b.patient({
    id: $.data.patientId,
    name: { family: $.data.lastName, given: $.data.firstName, use: 'official' },
    telecom: [{ system: 'phone', value: $.data.phone }],
  })
);

// Build a transaction bundle and upload it in one request.
createBundle({ type: 'transaction' });

// Add one or more resources to the default bundle.
addToBundle($.data.resources);

// POST the bundle to the server root.
uploadBundle();

// Find a Patient by identifier before creating a duplicate.
search('Patient', {
  query: { identifier: `urn:example:national-id|${$.data.nationalId}` },
});

// Get a patient's Observations updated since the last run.
search('Observation', {
  // Mapped to _lastUpdated.
  lastUpdated: `ge${$.cursor}`,
  // Mapped to _count.
  count: 100,
  query: { subject: `Patient/${$.data.patientId}` },
});

// Find Encounters at a facility from a given date.
search('Encounter', {
  query: {
    'service-provider': `Organization/${$.data.facilityId}`,
    date: `ge${$.data.startDate}`,
  },
  count: 50,
});

fhir-eswatini.code:
// Register a new patient.
create({
  resourceType: 'Patient',
  identifier: [
    {
      // Replace with your registry's identifier system URL for the national PIN.
      system: 'http://example.org/fhir/sid/sz-pin',
      value: $.data.pin,
    },
  ],
  name: [{ use: 'official', family: $.data.surname, given: [$.data.firstName] }],
  gender: $.data.sex === 'F' ? 'female' : 'male',
  birthDate: $.data.dateOfBirth, // YYYY-MM-DD
  telecom: [{ system: 'phone', value: $.data.phone, use: 'mobile' }],
});

// Replace a patient record with an updated version (PUT, so this also upserts).
update(`Patient/${$.data.patientId}`, {
  resourceType: 'Patient',
  id: $.data.patientId,
  name: [{ use: 'official', family: $.data.surname, given: [$.data.firstName] }],
  gender: 'female',
  birthDate: $.data.dateOfBirth,
  address: [{ use: 'home', city: $.data.town, district: $.data.region }],
});

// Record an outpatient visit.
create({
  resourceType: 'Encounter',
  status: 'finished',
  class: {
    system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
    code: 'AMB',
    display: 'ambulatory',
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  serviceProvider: { reference: `Organization/${$.data.facilityId}` },
  period: { start: $.data.visitStart, end: $.data.visitEnd },
});

// Record a lab result (HIV-1 viral load) against a patient and encounter.
create({
  resourceType: 'Observation',
  status: 'final',
  code: {
    coding: [{ system: 'http://loinc.org', code: '20447-9', display: 'HIV 1 RNA [#/volume] (viral load) in Serum or Plasma' }],
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  effectiveDateTime: $.data.sampleDate,
  valueQuantity: { value: $.data.viralLoad, unit: 'copies/mL', system: 'http://unitsofmeasure.org', code: '{copies}/mL' },
});

// Each resource needs an id: addToBundle upserts with PUT <resourceType>/<id>.
addToBundle([$.data.patient, $.data.encounter, ...$.data.observations]);

// Send the bundle (state.bundle) to the server as one transaction.
uploadBundle();

// Map free-text inkhundla names from the source system to SzTinkhundlaVS codes.
mapValues('http://172.209.216.154:3447/fhir/ValueSet/SzTinkhundlaVS', {
  lobamba: '3', // input value -> value set code
});

// Look up a patient by identifier (system|value, or just value).
search('Patient', {
  query: { identifier: $.data.pin },
});

// Set a cursor (last sync time) and fetch patients changed since then.
cursor($.lastSyncTime || '2026-01-01');

search('Patient', {
  lastUpdated: `ge${$.cursor}`,
  count: 100,
});

// Look up a health facility by its identifier (facility code).
search('Organization', {
  query: { identifier: $.data.facilityCode },
});

fhir-fr.code:
// This adaptor has no HTTP operations yet: build the resource on state,
// then send it in a later step (e.g. with the fhir-4 or http adaptor).
fn(state => {
  state.patient = {
    resourceType: 'Patient',
    meta: { profile: ['http://hl7.fr/ig/fhir/core/StructureDefinition/fr-core-patient'] },
    identifier: [
      {
        // INS (Identifiant National de Santé), NIR-based.
        system: 'urn:oid:1.2.250.1.213.1.4.8',
        value: state.data.ins,
      },
    ],
    name: [{ use: 'official', family: state.data.nom, given: [state.data.prenom] }],
    gender: state.data.sexe === 'F' ? 'female' : 'male',
    birthDate: state.data.dateNaissance, // YYYY-MM-DD
  };
  return state;
});

// Build a Practitioner identified by their RPPS number.
fn(state => {
  state.practitioner = {
    resourceType: 'Practitioner',
    meta: { profile: ['http://hl7.fr/ig/fhir/core/StructureDefinition/fr-core-practitioner'] },
    identifier: [
      {
        system: 'urn:oid:1.2.250.1.71.4.2.1', // idNatPS (RPPS-based)
        value: `8${state.data.rpps}`,
      },
    ],
    name: [{ family: state.data.nom, given: [state.data.prenom], prefix: ['Dr'] }],
  };
  return state;
});

// Wrap mapped resources in a transaction Bundle (each needs an id).
fn(state => {
  const resources = [state.patient, state.practitioner];
  state.bundle = {
    resourceType: 'Bundle',
    type: 'transaction',
    entry: resources.map(r => ({
      resource: r,
      request: { method: 'PUT', url: `${r.resourceType}/${r.id}` },
    })),
  };
  return state;
});

