// Verify the X-FormSG-Signature header and decrypt the submission.
// Needs formSecretKey and webhookEndpoint in the credential.
// FormSG posts { data: { formId, submissionId, encryptedContent, ... } }.
processWebhook(
  // 1) The encrypted submission from the webhook body.
  $.data.data,
  // 2) The signature header sent by FormSG.
  $.request.headers['x-formsg-signature']
);

// Decrypt a submission (handy when testing with a saved payload).
// state.data becomes { responses: [{ question, answer, fieldType, ... }] }.
decryptSubmission($.data.data);

// Decrypt only if the signature matches the configured webhookEndpoint.
decryptSubmission($.data.data, {
  verifySignature: true,
  signatureHeader: $.request.headers['x-formsg-signature'],
});

// 1) Verify and decrypt the submission.
processWebhook($.data.data, $.request.headers['x-formsg-signature']);

// 2) Flatten responses into { 'Full name': 'Tan Mei Ling', ... }.
fn(state => {
  state.answers = state.data.responses.reduce((acc, r) => {
    // Checkbox and table fields use answerArray instead of answer.
    acc[r.question] = r.answer ?? r.answerArray;
    return acc;
  }, {});
  return state;
});

gemini.code:
// Multi-turn chat. Pass an array of Content objects as the first argument;
// the adaptor forwards it as `contents` to generateContent.
prompt(
  [
    { role: 'user',  parts: [{ text: 'Hi there!' }] },
    { role: 'model', parts: [{ text: 'Hello — how can I help?' }] },
    { role: 'user',  parts: [{ text: $.data.userMessage }] },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

// Turn text into speech with a Gemini TTS model.
// prompt() only returns text, so call models.generateContent directly to get the audio bytes.
fn(async state => {
  const model = 'gemini-2.5-flash-preview-tts';
  const res = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
    {
      method: 'POST',
      headers: {
        'x-goog-api-key': state.configuration.apiKey,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        contents: [{ parts: [{ text: `Say clearly: ${state.data.message}` }] }],
        generationConfig: {
          responseModalities: ['AUDIO'],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      }),
    }
  );
  if (!res.ok) throw new Error(`Gemini API error ${res.status}: ${await res.text()}`);
  const body = await res.json();
  // Base64 audio (16-bit PCM, 24kHz mono) plus its mime type.
  const audio = body.candidates[0].content.parts[0].inlineData;
  state.data = { base64: audio.data, mimeType: audio.mimeType };
  return state;
});

// Generate an image from a text prompt.
// The base64-encoded image is written to state.
generateImage(
  `A flat-design illustration of: ${$.data.subject}`,
  {
    // Image-capable model — defaults to gemini-3-pro-image-preview.
    model: 'gemini-3-pro-image-preview',
    // Output size hint (e.g. '1K', '2K').
    imageSize: '1K',
    // Aspect ratio: '1:1', '16:9', '9:16', '4:3', '3:4'.
    aspectRatio: '16:9',
  }
);

// Generate a short video with Veo.
// The gemini adaptor has no video helper, so start a long-running predict job and poll it.
fn(async state => {
  const api = 'https://generativelanguage.googleapis.com/v1beta';
  const headers = { 'x-goog-api-key': state.configuration.apiKey, 'Content-Type': 'application/json' };

  // 1) Start the job.
  const start = await fetch(`${api}/models/veo-3.0-generate-001:predictLongRunning`, {
    method: 'POST',
    headers,
    body: JSON.stringify({
      instances: [{ prompt: `A short explainer animation: ${state.data.topic}` }],
      parameters: { aspectRatio: '16:9' },
    }),
  });
  if (!start.ok) throw new Error(`Gemini API error ${start.status}: ${await start.text()}`);
  let op = await start.json();

  // 2) Poll the operation (name looks like models/.../operations/...) until done.
  for (let i = 0; i < 30 && !op.done; i++) {
    await new Promise(r => setTimeout(r, 10000));
    op = await (await fetch(`${api}/${op.name}`, { headers })).json();
  }
  if (!op.done) throw new Error(`Video still generating: ${op.name}`);

  // The finished operation's response holds the generated video's download URI.
  state.data = op.response;
  return state;
});

// Send a prompt to Gemini.
// The text reply is written to state.data.response.
prompt(
  `Summarize this text: ${JSON.stringify($.data)}`,
  {
    // Gemini model id (see https://ai.google.dev/gemini-api/docs/models).
    model: 'gemini-2.5-flash',
    config: {
      temperature: 0.7,
    },
  }
);

// Summarize or transcribe an audio clip.
// prompt() forwards an array of Content objects to generateContent, so media goes in `parts`.
prompt(
  [
    {
      role: 'user',
      parts: [
        // Base64 audio, inline (keep the whole request under ~20MB).
        { inlineData: { mimeType: 'audio/mp3', data: $.data.audioBase64 } },
        { text: 'Transcribe this voice note, then list any follow-up actions mentioned.' },
      ],
    },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

// Ask questions about a document (PDF).
// prompt() forwards an array of Content objects to generateContent, so media goes in `parts`.
prompt(
  [
    {
      role: 'user',
      parts: [
        // Base64 PDF, inline (keep the whole request under ~20MB).
        { inlineData: { mimeType: 'application/pdf', data: $.data.pdfBase64 } },
        { text: 'Summarize this report in five bullet points and list key figures.' },
      ],
    },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

// Summarize a video clip and pull out key events.
// prompt() forwards an array of Content objects to generateContent, so media goes in `parts`.
prompt(
  [
    {
      role: 'user',
      parts: [
        // Base64 video, inline (keep the whole request under ~20MB).
        { inlineData: { mimeType: 'video/mp4', data: $.data.videoBase64 } },
        { text: 'Describe the key events in this video with approximate timestamps.' },
      ],
    },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

// Summarize a public YouTube video.
// prompt() forwards an array of Content objects to generateContent, so media goes in `parts`.
prompt(
  [
    {
      role: 'user',
      parts: [
        // Public YouTube URLs can be passed directly as fileData.
        { fileData: { fileUri: $.data.youtubeUrl } },
        { text: 'Summarize this video and list its key moments with timestamps.' },
      ],
    },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

