// Add a label to an email message.
// Use label ids (e.g. 'STARRED', 'IMPORTANT' or 'Label_123' from GET /users/me/labels), not names.
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${state.data.messageId}/modify`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ addLabelIds: [state.data.labelId] }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Archive an email by removing it from the inbox (the INBOX label).
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${state.data.messageId}/modify`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ removeLabelIds: ['INBOX'] }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Create a draft email (it is saved, not sent).
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  // Gmail expects a base64url-encoded RFC 2822 message.
  const raw = Buffer.from(
    [
      `To: ${state.data.to}`,
      `Subject: ${state.data.subject}`,
      'Content-Type: text/plain; charset=UTF-8',
      '',
      state.data.body,
    ].join('\r\n')
  ).toString('base64url');

  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/drafts`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ message: { raw } }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Create a draft reply in an existing conversation.
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  // Reply headers: threadId plus In-Reply-To/References (the original's Message-ID header)
  // keep the reply in the same conversation.
  const raw = Buffer.from(
    [
      `To: ${state.data.from}`,
      `Subject: Re: ${state.data.subject}`,
      `In-Reply-To: ${state.data.rfcMessageId}`,
      `References: ${state.data.rfcMessageId}`,
      'Content-Type: text/plain; charset=UTF-8',
      '',
      state.data.replyBody,
    ].join('\r\n')
  ).toString('base64url');

  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/drafts`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ message: { raw, threadId: state.data.threadId } }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Create a new label.
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/labels`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name: 'Referrals/Pending',
      labelListVisibility: 'labelShow',
      messageListVisibility: 'show',
    }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  // Response includes the new label's id, for use with messages.modify.
  state.data = await res.json();
  return state;
});

// Move an email message to the trash.
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${state.data.messageId}/trash`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
    },
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Remove a label from every message in a conversation (thread).
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/threads/${state.data.threadId}/modify`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ removeLabelIds: [state.data.labelId] }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Remove a label from a single email message.
// The gmail adaptor has no helper for this, so call the Gmail API directly.
fn(async state => {
  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${state.data.messageId}/modify`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ removeLabelIds: [state.data.labelId] }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Send a reply in an existing conversation.
// sendMessage() can't set threadId or reply headers, so call the Gmail API directly.
fn(async state => {
  // Reply headers: threadId plus In-Reply-To/References (the original's Message-ID header)
  // keep the reply in the same conversation.
  const raw = Buffer.from(
    [
      `To: ${state.data.from}`,
      `Subject: Re: ${state.data.subject}`,
      `In-Reply-To: ${state.data.rfcMessageId}`,
      `References: ${state.data.rfcMessageId}`,
      'Content-Type: text/plain; charset=UTF-8',
      '',
      state.data.replyBody,
    ].join('\r\n')
  ).toString('base64url');

  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/send`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ raw, threadId: state.data.threadId }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Send a new email through Gmail.
// Pass a single message object, or an array to send several in one step.
sendMessage({
  // Recipient address (or an array of addresses).
  to: 'recipient@example.org',
  // Subject line.
  subject: 'Hello from OpenFn',
  // Message body. Plain text by default; pass html: true for HTML.
  body: `Hi there,\n\nThis email was sent from an OpenFn workflow.`,
  // Optional CC / BCC.
  // cc: 'cc@example.org',
  // bcc: 'bcc@example.org',
  // Optional file attachments.
  // attachments: [{ filename: 'report.csv', content: $.csv }],
});

// Find emails matching a Gmail search query.
// Results land on state.data as an array of message contents.
getContentsFromMessages({
  // Standard Gmail search syntax (from:, subject:, after:, has:attachment, ...).
  query: 'from:billing@example.org subject:invoice after:2026/01/01',
  // Which fields to pull back per message.
  contents: ['from', 'date', 'subject', 'body'],
  // Cap the number of messages returned.
  maxResults: 25,
});

// Find the latest email with a given attachment and pull that file's contents.
getContentsFromMessages({
  // Gmail search syntax: narrow to messages carrying this filename.
  query: `has:attachment filename:${$.data.fileName}`,
  contents: [
    'subject',
    // `file` matches the attachment name (string or RegExp); `name` is the output key.
    { type: 'file', name: 'attachment', file: $.data.fileName },
  ],
  maxResults: 1,
});

