    value: $.data.centreName,
    code: $.data.centreCode,
    description: 'Synced from the national facility registry',
    active: true,
  }
);

// Find confirmed cases in an outbreak using a Loopback "where" filter.
getCase(
  // 1) Outbreak id (string literal).
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Filter sent as ?filter=...
  {
    where: {
      classification: 'LNG_REFERENCE_DATA_CATEGORY_CASE_CLASSIFICATION_CONFIRMED',
      dateOfReporting: { gte: '2026-10-01' },
    },
  }
);

// Find a contact by visualId.
getContact(
  // 1) Outbreak id (string literal).
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Loopback filter.
  { where: { visualId: 'CON-2026-00042' } }
);

// Get all reference data items in one category (here: case classifications).
getReferenceData({
  where: { categoryId: 'LNG_REFERENCE_DATA_CATEGORY_CASE_CLASSIFICATION' },
});

googledrive.code:
// Make a copy of a file, optionally renaming it and placing it in another folder.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}/copy?supportsAllDrives=true`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name: `Copy of ${state.data.fileName}`,
      parents: [state.configuration.parentFolderId],
    }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// 1) Download the file from another service's URL (e.g. a form attachment link).
fn(async state => {
  const res = await fetch(state.data.fileUrl);
  if (!res.ok) throw new Error(`Download failed: ${res.status}`);
  // create() expects base64-encoded content.
  state.fileBase64 = Buffer.from(await res.arrayBuffer()).toString('base64');
  return state;
});

// 2) Upload it to Drive.
create(
  // 1) Base64 file content.
  $.fileBase64,
  // 2) File name in Drive.
  $.data.fileName,
  // 3) Optional target folder.
  { folderId: $.configuration.parentFolderId }
);

// Create a new file from a string of text.
create(
  // 1) File body (text or binary buffer).
  `Report generated on ${new Date().toISOString()}\n\n${$.data.body}`,
  // 2) File name (extension determines the default mime type).
  'report.txt'
);

// Create an empty folder.
// Pass `null` for content and the folder mime type via options.
create(null, 'My new folder', {
  mimeType: 'application/vnd.google-apps.folder',
});

// Create a new shared drive.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
// requestId is an idempotency key: reuse it to safely retry the same create.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/drives?requestId=${encodeURIComponent(state.data.requestId)}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ name: `${state.data.programmeName} - field reports` }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Create a shortcut to an existing file inside another folder.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?supportsAllDrives=true`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name: state.data.shortcutName,
      // Shortcuts are files with this special mime type.
      mimeType: 'application/vnd.google-apps.shortcut',
      shortcutDetails: { targetId: state.data.fileId },
      parents: [state.configuration.parentFolderId],
    }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Move a file to the trash (it can still be restored from Drive's Trash).
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}?supportsAllDrives=true`, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ trashed: true }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Export a Google Doc / Sheet / Slides file to another format (here: PDF).
// The googledrive adaptor has no helper for this, so call the Drive API directly.
// Other mimeTypes: application/vnd.openxmlformats-officedocument.wordprocessingml.document (.docx),
// application/vnd.openxmlformats-officedocument.spreadsheetml.sheet (.xlsx), text/csv.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}/export?mimeType=${encodeURIComponent('application/pdf')}`, {
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  // Exported bytes as base64, ready to pass to create() or another system.
  state.data = { base64: Buffer.from(await res.arrayBuffer()).toString('base64') };
  return state;
});

// Move a file from one folder to another.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}?` +
    `addParents=${state.data.targetFolderId}&removeParents=${state.data.sourceFolderId}&supportsAllDrives=true`, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({}),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Permanently delete a file, skipping the trash. This cannot be undone.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}?supportsAllDrives=true`, {
    method: 'DELETE',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  // A successful delete returns 204 with no body.
  return state;
});

// Remove one user's access to a file.
// The googledrive adaptor has no helper for permissions, so call the Drive API directly.
fn(async state => {
  const headers = { Authorization: `Bearer ${state.configuration.access_token}` };
  const base = `https://www.googleapis.com/drive/v3/files/${state.data.fileId}/permissions`;

  // 1) Find the permission id for this user's email.
  const listRes = await fetch(`${base}?fields=permissions(id,emailAddress,role)&supportsAllDrives=true`, { headers });
  if (!listRes.ok) throw new Error(`Drive API error ${listRes.status}: ${await listRes.text()}`);
  const { permissions = [] } = await listRes.json();
  const permission = permissions.find(p => p.emailAddress === state.data.email);
  if (!permission) throw new Error(`${state.data.email} has no access to this file`);

  // 2) Delete that permission.
  const res = await fetch(`${base}/${permission.id}?supportsAllDrives=true`, { method: 'DELETE', headers });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  return state;
});

// Upload a file's contents to Drive.
// `content` can be a string or a Buffer; the file name carries the extension.
create(
  $.data.fileContent,
  $.data.fileName,
  {
    // Optional parent folder id.
    parents: [$.configuration.parentFolderId],
    // Optional mime type override.
    mimeType: 'text/csv',
  }
);

// Make a raw, authenticated request to the Google Drive API.
// Any path under https://www.googleapis.com/drive/v3 works; here we read the current user and storage quota.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/about?fields=user,storageQuota`, {
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Search for files by name. `list` returns matching items on state.data.
list(
  // 1) Folder id to scope the search to (or null to search the whole Drive).
  $.configuration.parentFolderId,
  // 2) Drive list query options.
  {
    // Drive query syntax: https://developers.google.com/drive/api/guides/search-files
    q: `name = '${$.data.fileName}' and trashed = false`,
    fields: 'files(id,name,mimeType,modifiedTime)',
  }
);

// Search for folders by name.
list(null, {
  q: `mimeType = 'application/vnd.google-apps.folder' and name = '${$.data.folderName}' and trashed = false`,
  fields: 'files(id,name)',
});

// Keep the incoming payload: list() replaces state.data with its results.
fn(state => ({ ...state, input: state.data }));

// 1) Look for the file by name in the folder.
list($.configuration.parentFolderId, {
  query: `name = '${$.input.fileName}' and trashed = false`,
  fields: ['id', 'name', 'mimeType', 'modifiedTime'],
  limit: 1,
});

// 2) Nothing found? Upload it (content must be base64).
fnIf(
  state => state.data.length === 0,
  create($.input.fileBase64, $.input.fileName, {
    folderId: $.configuration.parentFolderId,
  })
);

// Keep the incoming payload: list() replaces state.data with its results.
fn(state => ({ ...state, input: state.data }));

// 1) Look for a sub-folder with this name inside the parent folder.
list($.configuration.parentFolderId, {
  query: `mimeType = 'application/vnd.google-apps.folder' and name = '${$.input.folderName}' and trashed = false`,
  fields: ['id', 'name'],
  limit: 1,
});

// 2) Nothing found? Create it. create() only uploads files, so call the Drive API for folders.
fnIf(
  state => state.data.length === 0,
  fn(async state => {
    const res = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: state.input.folderName,
        mimeType: 'application/vnd.google-apps.folder',
        parents: [state.configuration.parentFolderId],
      }),
    });
    if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
    state.data = [await res.json()];
    return state;
  })
);

// List everyone who has access to a file, and their role.
// The googledrive adaptor has no helper for permissions, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}/permissions?` +
    `fields=permissions(id,type,role,emailAddress,displayName)&supportsAllDrives=true`, {
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  // Each permission has a role: owner, organizer, writer, commenter or reader.
  state.data = (await res.json()).permissions;
  return state;
});

// List files inside a folder.
list(
  $.configuration.parentFolderId,
  {
    fields: 'files(id,name,mimeType,modifiedTime)',
    pageSize: 100,
  }
);

googlehealthcare.code:
// Register a patient in the shared health record FHIR store.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The FHIR resource; resourceType decides the endpoint.
  {
    resourceType: 'Patient',
    identifier: [{ system: 'http://moh.example.org/national-id', value: $.data.nationalId }],
    name: [{ use: 'official', family: $.data.lastName, given: [$.data.firstName] }],
    gender: $.data.sex,
    birthDate: $.data.dateOfBirth,
  }
);

// Log an outpatient visit for an existing patient.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Encounter, referencing the patient by id.
  {
    resourceType: 'Encounter',
    status: 'finished',
    class: { system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode', code: 'AMB', display: 'ambulatory' },
    subject: { reference: `Patient/${$.data.patientId}` },
    period: { start: $.data.checkInTime, end: $.data.checkOutTime },
  }
);

// Store an HIV viral load result from the lab system.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Observation (LOINC 25836-8 = HIV-1 RNA viral load).
  {
    resourceType: 'Observation',
    status: 'final',
    code: { coding: [{ system: 'http://loinc.org', code: '25836-8' }] },
    subject: { reference: `Patient/${$.data.patientId}` },
    effectiveDateTime: $.data.sampleDate,
    valueQuantity: { value: $.data.copiesPerMl, unit: 'copies/mL' },
  }
);

// Record a measles vaccine dose given during an outreach campaign.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Immunization (CVX 05 = measles).
  {
    resourceType: 'Immunization',
    status: 'completed',
    vaccineCode: { coding: [{ system: 'http://hl7.org/fhir/sid/cvx', code: '05' }] },
    patient: { reference: `Patient/${$.data.patientId}` },
    occurrenceDateTime: $.data.dateGiven,
    lotNumber: $.data.lotNumber,
  }
);

// Record a confirmed malaria diagnosis.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Condition, coded with ICD-10.
  {
    resourceType: 'Condition',
    clinicalStatus: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-clinical', code: 'active' }] },
    verificationStatus: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-ver-status', code: 'confirmed' }] },
    code: { coding: [{ system: 'http://hl7.org/fhir/sid/icd-10', code: 'B54', display: 'Unspecified malaria' }] },
    subject: { reference: `Patient/${$.data.patientId}` },
    onsetDateTime: $.data.diagnosisDate,
  }
);

// Create one Patient per record in an incoming list.
each(
  $.data.patients,
  createFhirResource(
    // 1) The target FHIR store (all four keys are required).
    {
      cloudRegion: 'europe-west4',
      projectId: 'moh-health-data',
      datasetId: 'national-hie',
      fhirStoreId: 'shr-r4',
    },
    // 2) Inside each(), $.data is the current item.
    {
      resourceType: 'Patient',
      name: [{ family: $.data.lastName, given: [$.data.firstName] }],
      birthDate: $.data.dateOfBirth,
    }
  )
);

googlesheets.code:
// Freeze the header row, move the tab to first position and make sure it's visible.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            updateSheetProperties: {
              properties: {
                // Numeric sheet id (the `gid` in the sheet URL), not the tab name.
                sheetId: state.data.sheetId,
                index: 0,
                hidden: false,
                gridProperties: { frozenRowCount: 1, frozenColumnCount: 0 },
              },
              // Only the listed fields are changed.
              fields: 'index,hidden,gridProperties.frozenRowCount,gridProperties.frozenColumnCount',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Clear cell contents in a row (or rows) by writing empty strings.
// The row(s) themselves stay in place; only the values are wiped.
batchUpdateValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      // A1 range covering the row(s) to clear.
      range: 'Sheet1!A5:Z5',
      // One inner array per row, sized to the range.
      values: [Array(26).fill('')],
    },
  ],
});

// Copy A1:D20 from one tab to another, pasting values only.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            copyPaste: {
              // Ranges use numeric sheet ids and zero-based, end-exclusive indexes.
              source: {
                sheetId: state.data.sourceSheetId,
                startRowIndex: 0, endRowIndex: 20,
                startColumnIndex: 0, endColumnIndex: 4,
              },
              destination: {
                sheetId: state.data.targetSheetId,
                startRowIndex: 0, endRowIndex: 20,
                startColumnIndex: 0, endColumnIndex: 4,
              },
              // PASTE_NORMAL, PASTE_VALUES, PASTE_FORMAT, PASTE_NO_BORDERS, ...
              pasteType: 'PASTE_VALUES',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Copy a worksheet (tab) into the same or another spreadsheet.
// No adaptor helper for this, so call POST .../sheets/{sheetId}:copyTo directly.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/sheets/${state.data.sheetId}:copyTo`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      // Use the same id to duplicate the tab within this spreadsheet.
      body: JSON.stringify({ destinationSpreadsheetId: spreadsheetId }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  // Response is the new sheet's properties (sheetId, title, index).
  state.data = await res.json();
  return state;
});

// Highlight stock levels below 10 in red (column C, from row 2 down).
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            addConditionalFormatRule: {
              index: 0,
              rule: {
                ranges: [
                  { sheetId: state.data.sheetId, startRowIndex: 1, startColumnIndex: 2, endColumnIndex: 3 },
                ],
                booleanRule: {
                  condition: {
                    type: 'NUMBER_LESS',
                    values: [{ userEnteredValue: '10' }],
                  },
                  format: {
                    backgroundColor: { red: 0.96, green: 0.8, blue: 0.8 },
                    textFormat: { bold: true },
                  },
                },
              },
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Append many rows in one call.
// Each inner array is one row; cells must line up with your columns.
appendValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  range: 'Sheet1!A1:D1',
  values: $.data.records.map(r => [r.name, r.email, r.amount, r.date]),
});

// Create a new spreadsheet with a named tab.
// No adaptor helper for this, so call POST /v4/spreadsheets directly.
fn(async state => {
  const res = await fetch('https://sheets.googleapis.com/v4/spreadsheets', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      properties: { title: `Clinic visits ${new Date().toISOString().slice(0, 10)}` },
      sheets: [{ properties: { title: 'Visits' } }],
    }),
  });
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  // Response includes spreadsheetId and spreadsheetUrl.
  state.data = await res.json();
  return state;
});

// Optional: add a header row to the new sheet.
appendValues({
  spreadsheetId: $.data.spreadsheetId,
  range: 'Visits!A1:D1',
  values: [['Patient ID', 'Visit date', 'Facility', 'Outcome']],
});

// Add a new column by writing its header into the next empty column.
// Existing columns here are A-D, so the new column goes in E.
batchUpdateValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      // Header cell for the new column.
      range: 'Sheet1!E1',
      values: [['Follow-up date']],
    },
  ],
});

// Append a single row to the bottom of a sheet.
appendValues({
  // Spreadsheet ID — the long string from the sheet's URL.
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  // Where to append. Sheet name + column range.
  range: 'Sheet1!A1:D1',
  // Outer array = rows, inner arrays = cells in column order.
  values: [
    [$.data.name, $.data.email, $.data.amount, $.data.date],
  ],
});

// 1) Insert an empty row directly below the header (row 2).
// No adaptor helper for inserting rows, so call the batchUpdate endpoint directly.
// state.data is left untouched so step 2 can still read the incoming payload.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            insertDimension: {
              // Zero-based, end-exclusive: inserts one row at row 2.
              range: { sheetId: state.data.sheetId, dimension: 'ROWS', startIndex: 1, endIndex: 2 },
              inheritFromBefore: false,
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  return state;
});

// 2) Write the new values into that row.
batchUpdateValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      range: 'Sheet1!A2:D2',
      values: [[$.data.name, $.data.email, $.data.amount, $.data.date]],
    },
  ],
});

// Add a new worksheet (tab) to an existing spreadsheet.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
