      },
      body: JSON.stringify({
        requests: [
          {
            deleteDimension: {
              range: {
                sheetId: state.data.sheetId,
                dimension: 'ROWS',
                // Zero-based, end-exclusive: 4..7 removes sheet rows 5, 6 and 7.
                startIndex: 4,
                endIndex: 7,
              },
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
