});

// Format B2:B100 as dates and C2:C100 as bold currency.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            repeatCell: {
              range: { sheetId: state.data.sheetId, startRowIndex: 1, endRowIndex: 100, startColumnIndex: 1, endColumnIndex: 2 },
              cell: { userEnteredFormat: { numberFormat: { type: 'DATE', pattern: 'yyyy-mm-dd' } } },
              fields: 'userEnteredFormat.numberFormat',
            },
          },
          {
            repeatCell: {
              range: { sheetId: state.data.sheetId, startRowIndex: 1, endRowIndex: 100, startColumnIndex: 2, endColumnIndex: 3 },
              cell: {
                userEnteredFormat: {
                  numberFormat: { type: 'CURRENCY', pattern: '$#,##0.00' },
                  textFormat: { bold: true, italic: false, strikethrough: false },
                },
              },
              fields: 'userEnteredFormat(numberFormat,textFormat)',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Style the header row: bold white text on a dark blue background.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
