          {
            repeatCell: {
              // Row 1 only (zero-based, end-exclusive), all columns.
              range: { sheetId: state.data.sheetId, startRowIndex: 0, endRowIndex: 1 },
              cell: {
                userEnteredFormat: {
                  backgroundColor: { red: 0.12, green: 0.25, blue: 0.5 },
                  textFormat: { bold: true, foregroundColor: { red: 1, green: 1, blue: 1 } },
                },
              },
              fields: 'userEnteredFormat(backgroundColor,textFormat)',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Rename a worksheet (tab).
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            updateSheetProperties: {
              properties: { sheetId: state.data.sheetId, title: state.data.newTitle },
              // Only change the title.
              fields: 'title',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Restrict column D (from row 2) to a dropdown of visit outcomes.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            setDataValidation: {
              range: { sheetId: state.data.sheetId, startRowIndex: 1, startColumnIndex: 3, endColumnIndex: 4 },
              rule: {
                condition: {
                  type: 'ONE_OF_LIST',
                  values: [
                    { userEnteredValue: 'Completed' },
                    { userEnteredValue: 'Referred' },
                    { userEnteredValue: 'No show' },
                  ],
                },
                // Reject anything not in the list and show a dropdown.
                strict: true,
                showCustomUi: true,
              },
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Sort A2:D500 by column D (date), newest first; the header row stays put.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            sortRange: {
              range: { sheetId: state.data.sheetId, startRowIndex: 1, endRowIndex: 500, startColumnIndex: 0, endColumnIndex: 4 },
              sortSpecs: [
                // dimensionIndex is the zero-based column within the sheet.
                { dimensionIndex: 3, sortOrder: 'DESCENDING' },
              ],
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Overwrite the values of a single row.
batchUpdateValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  // Parse cell input like a user typed it (formulas, dates, etc.).
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      range: 'Sheet1!A5:D5',
      values: [[$.data.name, $.data.email, $.data.amount, $.data.date]],
    },
  ],
});

// Overwrite multiple ranges in one batch.
batchUpdateValues({
  spreadsheetId: '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  valueInputOption: 'USER_ENTERED',
  data: $.data.updates.map(u => ({
    range: u.range,
    values: [u.row],
  })),
});

// Make a raw, authenticated request to the Google Sheets API.
// Any path from https://sheets.googleapis.com/v4/... works; here we read two ranges at once.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const params = new URLSearchParams([['ranges', 'Sheet1!A1:D10'], ['ranges', 'Sheet2!A1:B5']]);
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values:batchGet?${params}`,
    { headers: { Authorization: `Bearer ${state.configuration.access_token}` } }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Find a worksheet (tab) by title.
// No adaptor helper for sheet metadata, so call GET /v4/spreadsheets/{spreadsheetId} directly.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}?fields=sheets.properties`,
    { headers: { Authorization: `Bearer ${state.configuration.access_token}` } }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  const { sheets = [] } = await res.json();
  // Match on title; `found` is undefined if there's no such tab.
  // To create it when missing, follow with an addSheet batchUpdate (see "Create Worksheet").
  state.found = sheets.map(s => s.properties).find(p => p.title === state.data.worksheetTitle);
  return state;
});

// Read values from an A1 range. Result is on state.data as a 2d array.
getValues(
  // Spreadsheet ID.
  '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  // A1 range — sheet name + range.
  'Sheet1!A1:D100'
);

// Pull a wide range and return all rows.
getValues(
  '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  // Open-ended range — fetches every populated row in the column span.
  'Sheet1!A2:Z'
);

// Fetch a single row by its row number (1-based).
const rowId = $.data.rowId;
getValues(
  '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  // Build an A1 range that spans only that row.
  `Sheet1!A${rowId}:Z${rowId}`
);

// Get a spreadsheet's raw metadata (title, locale, sheets and their properties).
// No adaptor helper for this, so call GET /v4/spreadsheets/{spreadsheetId} directly.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    // includeGridData=false keeps the response small (no cell data).
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}?includeGridData=false`,
    { headers: { Authorization: `Bearer ${state.configuration.access_token}` } }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

// Read a range, then filter in the callback to find the matching row.
getValues(
  '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  'Sheet1!A1:D100',
  // Callback receives state with rows on state.data.values.
  state => {
    const [header, ...rows] = state.data.values || [];
    // Match on the second column (index 1).
    state.match = rows.find(r => r[1] === $.data.email);
    return state;
  }
);

// Read a range, then filter in the callback for all matches.
getValues(
  '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos',
  'Sheet1!A1:D500',
  state => {
    const [header, ...rows] = state.data.values || [];
    state.matches = rows.filter(r => r[1] === $.data.email);
    return state;
  }
);

