ibipimo.code:
// Send a viral load test request for one sample to the lab.
postViralLoadRequest({
  siteid: $.data.siteId, // the facility's IBIPIMO site id
  samples: [
    {
      sidainfo_uid: $.data.sidainfoUid, // id in the EMR (SIDAInfo)
      p_code: $.data.patientCode,
      p_name: $.data.lastName,
      p_prename: $.data.firstName,
      p_sex: $.data.sex, // 'M' | 'F'
      p_dob: $.data.dateOfBirth, // 'YYYY-MM-DD'
      arv_start_date: $.data.arvStartDate,
      date_blood_taken: $.data.collectedAt, // 'YYYY-MM-DD HH:mm:ss'
      reason_vl: 'suspicion_echec',
      on_arv: '1',
      sample_type: 'DBS',
    },
  ],
});

// Send every sample in the incoming EMR export in one request.
postViralLoadRequest({
  siteid: $.data.siteId,
  samples: $.data.samples.map(s => ({
    sidainfo_uid: s.id,
    p_code: s.patientCode,
    p_name: s.lastName,
    p_prename: s.firstName,
    p_sex: s.sex,
    p_dob: s.dateOfBirth,
    date_blood_taken: s.collectedAt,
    sample_type: s.sampleType, // e.g. 'DBS' or 'Plasma'
  })),
});

// After postViralLoadRequest(), pull out saved sample ids and errors.
processViralLoadSubmission((state, processSubmission) => {
  const result = processSubmission(state.data);
  if (result.hasErrors) {
    console.log(`${result.errorCount} samples were rejected`);
    return { ...state, errors: result.errors };
  }
  // Lab sample ids to store back in the EMR.
  return { ...state, labSampleIds: result.sampleIds };
});

// Ask the lab for results of samples sent earlier.
getViralLoadResults({
  siteid: $.data.siteId,
  sample_uids: $.data.sampleUids, // e.g. ['2026010401', '2026010402']
});

// After getViralLoadResults(), split published results from pending samples.
processViralLoadResults((state, processResults) => {
  const processed = processResults(state.data);
  console.log(`Found ${processed.totalFound}/${processed.totalRequested} results`);
  return {
    ...state,
    readyForEmr: processed.availableResults, // write these back to the EMR
    pendingSamples: processed.pendingSamples, // retry on the next run
  };
});

// List the processing status of a site's samples.
get('/api/v1/samples/status', {
  query: { siteid: $.data.siteId },
});

// List active sites, e.g. to map EMR facilities to IBIPIMO site ids.
get('/api/v1/sites', {
  query: { active: true },
});

ihris.code:
// Create a health worker (FHIR Practitioner).
// http.* paths are relative to the iHRIS baseUrl; login is handled for you.
http.post('/fhir/Practitioner', {
  resourceType: 'Practitioner',
  meta: {
    profile: ['http://ihris.org/fhir/StructureDefinition/ihris-practitioner'],
  },
  identifier: [
    { system: 'http://moh.example.gov/fhir/license', value: $.data.licenseNumber },
  ],
  name: [{ use: 'official', family: $.data.lastName, given: [$.data.firstName] }],
  gender: $.data.gender, // 'male' | 'female' | 'other' | 'unknown'
  birthDate: $.data.dateOfBirth, // YYYY-MM-DD
  telecom: [{ system: 'phone', value: $.data.phone }],
  active: true,
});

// Update a health worker record by id (full resource replace).
http.put(
  // 1) Resource path, including the Practitioner id.
  `/fhir/Practitioner/${$.data.practitionerId}`,
  // 2) The full updated resource.
  {
    resourceType: 'Practitioner',
    id: $.data.practitionerId,
    name: [{ use: 'official', family: $.data.lastName, given: [$.data.firstName] }],
    telecom: [{ system: 'phone', value: $.data.phone }],
    active: $.data.status === 'active',
  }
);

// Submit a FHIR transaction Bundle.
http.post('/fhir', {
  resourceType: 'Bundle',
  type: 'transaction',
  entry: [
    {
      fullUrl: 'urn:uuid:practitioner-1',
      resource: {
        resourceType: 'Practitioner',
        name: [{ family: $.data.lastName, given: [$.data.firstName] }],
      },
      request: { method: 'POST', url: 'Practitioner' },
    },
    {
      resource: {
        resourceType: 'PractitionerRole',
        practitioner: { reference: 'urn:uuid:practitioner-1' },
        location: [{ reference: `Location/${$.data.facilityId}` }],
        active: true,
      },
      request: { method: 'POST', url: 'PractitionerRole' },
    },
  ],
});

// Fetch practitioners. fhir.get() pages through all results for you.
fhir.get('Practitioner', {
  count: 100, // page size (_count)
  sort: '-_lastUpdated', // newest first (_sort)
});

// Fetch practitioners updated since a given date.
fhir.get('Practitioner', {
  // Maps to _lastUpdated; 'gt' means 'after'.
  lastUpdated: `gt${$.data.lastSyncDate}`, // e.g. gt2026-01-01
  count: 100,
});

// Fetch job assignments (PractitionerRole) and the linked practitioners.
fhir.get('PractitionerRole', {
  include: 'PractitionerRole:practitioner', // maps to _include
  count: 100,
});

// Fetch facilities / duty stations.
fhir.get('Location', {
  count: 200,
  elements: 'id,name,identifier,partOf', // maps to _elements
});

