mailchimp.code:
// Add a note to an existing subscriber.
// The subscriber can be identified by email address or its MD5 hash.
post(`/lists/${$.configuration.listId}/members/${$.data.email}/notes`, {
  note: `Attended the nutrition workshop on ${$.data.eventDate}.`,
});

// Add or update one or more subscribers on a list.
upsertMembers({
  // The Mailchimp audience (list) id.
  listId: $.configuration.listId,
  // Array of users to upsert.
  users: [
    {
      email: $.data.email,
      status: 'subscribed',
      mergeFields: { FNAME: $.data.firstName, LNAME: $.data.lastName },
    },
  ],
});

// Archive a single subscriber by email.
archiveMember({
  listId: $.configuration.listId,
  email:  $.data.email,
});

// Create a new audience (list).
post('/lists', {
  name: 'Community health volunteers',
  // Reminder of why people are receiving your emails.
  permission_reminder: 'You signed up as a volunteer at one of our clinics.',
  email_type_option: false,
  // Required postal contact details (shown in email footers).
  contact: {
    company: 'Example Health Foundation',
    address1: '12 Clinic Road',
    city: 'Nairobi',
    country: 'KE',
  },
  campaign_defaults: {
    from_name: 'Example Health Foundation',
    from_email: 'updates@example.org',
    subject: 'Volunteer update',
    language: 'en',
  },
});

// Create a draft email campaign for an audience.
post('/campaigns', {
  type: 'regular',
  recipients: {
    list_id: $.configuration.listId,
  },
  settings: {
    subject_line: 'Vaccination days this month',
    title: `Vaccination reminder ${$.data.month}`,
    from_name: 'Example Health Foundation',
    reply_to: 'updates@example.org',
  },
});

// Record a custom event for a subscriber (can trigger automations).
post(`/lists/${$.configuration.listId}/members/${$.data.email}/events`, {
  // Event name, 2-30 characters.
  name: 'completed_training',
  // Optional string properties.
  properties: {
    course: $.data.courseName,
  },
});

// Create a new tag (a static segment) on an audience.
post(`/lists/${$.configuration.listId}/segments`, {
  name: 'Malaria programme',
  // Emails to tag straight away; pass [] to create an empty tag.
  static_segment: [$.data.email],
});

// Permanently delete a member (cannot be undone; member can't be re-subscribed).
deleteMember({
  listId: $.configuration.listId,
  email:  $.data.email,
});

// Remove a tag from a subscriber by marking the tag as inactive.
updateMemberTags({
  listId: $.configuration.listId,
  email:  $.data.email,
  tags: [
    { name: $.data.tagName, status: 'inactive' },
  ],
});

// Unsubscribe a member (set status to 'unsubscribed').
updateMember({
  listId: $.configuration.listId,
  email:  $.data.email,
  status: 'unsubscribed',
});

// Make an arbitrary request to the Mailchimp API.
// Path is relative to https://{dc}.api.mailchimp.com/3.0
request('GET', '/ping');

// Search campaigns by title or subject.
get('/search-campaigns', { query: $.data.campaignTitle });

// If nothing matched, create a draft campaign with that title.
fnIf(
  state => !state.data.results?.length,
  post('/campaigns', {
    type: 'regular',
    recipients: { list_id: $.configuration.listId },
    settings: {
      title: $.data.campaignTitle,
      subject_line: $.data.campaignTitle,
      from_name: 'Example Health Foundation',
      reply_to: 'updates@example.org',
    },
  })
);

// Look for the subscriber on the audience by email.
get('/search-members', {
  query: $.data.email,
  list_id: $.configuration.listId,
});

// If there's no exact match, add them as a new subscriber.
fnIf(
  state => !state.data.exact_matches?.members?.length,
  post(`/lists/${$.configuration.listId}/members`, {
    email_address: $.data.email,
    status: 'subscribed',
    merge_fields: { FNAME: $.data.firstName, LNAME: $.data.lastName },
  })
);

// Look up segments (tags) for a list.
get(`/lists/${$.configuration.listId}/segments`, {
  type: 'static',
});

mailgun.code:
// Add a member to a mailing list.
// The adaptor only exposes send(), so this uses the mailgun.js client it
// sets up on state.client.
fn(async state => {
  const member = await state.client.lists.members.createMember(
    // The mailing list address.
    'volunteers@mg.example.org',
    {
      address: state.data.email,
      name: state.data.name,
      subscribed: 'yes',
      // Update the member if they already exist.
      upsert: 'yes',
    }
  );
  return { ...state, data: member };
});

// Upload a CSV of emails and start a bulk validation job (Mailgun v4 API).
// The adaptor only exposes send(), so this uses the mailgun.js client it
// sets up on state.client.
fn(async state => {
  // One email per line, with a header row.
  const csv = ['email', ...state.data.emails].join('\n');

  const job = await state.client.validate.multipleValidation.create(
    // A name for this validation job / list.
    'volunteer-emails-2026',
    { file: { filename: 'emails.csv', data: csv } }
  );
  return { ...state, data: job };
});

// Fetch the status and results of a bulk validation job.
// The adaptor only exposes send(), so this uses the mailgun.js client it
// sets up on state.client.
fn(async state => {
  const job = await state.client.validate.multipleValidation.get(
    // The job / list name used when the job was created.
    state.data.validationJobId
  );
  // job.status, job.summary and job.downloadUrl (csv / json) hold the results.
  return { ...state, data: job };
});

// Send an email via Mailgun.
send({
  // Sender address. Use a domain you've verified in Mailgun.
  from: `OpenFn <noreply@${$.configuration.domain}>`,
  // Recipient (string, or array for multiple).
  to: $.data.recipient,
  subject: $.data.subject,
  // Plain-text and / or HTML bodies.
  text: $.data.body,
  // html: `<p>${$.data.body}</p>`,
});

// Validate a single email address (Mailgun v4 API).
// The adaptor only exposes send(), so this uses the mailgun.js client it
// sets up on state.client.
fn(async state => {
  const result = await state.client.validate.get(state.data.email);
  // result.result is e.g. 'deliverable', 'undeliverable' or 'unknown'.
  return { ...state, data: result };
});

// The adaptor has no generic request helper: it only exposes send().
// Closest option: call a method on the mailgun.js client it sets up on
// state.client. For example, list the account's mailing lists:
fn(async state => {
  const lists = await state.client.lists.list();
  return { ...state, data: lists };
});

