// Get new submissions of the pregnancy registration form and forward each one.
fetchSubmissions(
  // 1) The CHT form id to pick out of the changes feed.
  'pregnancy',
  // 2) Changes feed params; the cursor from the last run is used automatically.
  { 'last-event-id': 0 },
  // 3) Each submission is POSTed here (e.g. a workflow's webhook URL).
  $.configuration.webhookUrl
);

// Read changes since the last run, with full documents.
changesApi({
  include_docs: true,
  // Used on the first run only; later runs use state.cursor.
  'last-event-id': 0,
});

// Read changes for specific documents only.
changesApi({
  include_docs: true,
  // Document ids to filter on.
  doc_ids: $.data.contactIds,
});

// Read changes, then keep only reports for one form.
changesApi(
  { include_docs: true },
  // Callback: filter the results to 'delivery' reports.
  state => {
    const reports = state.data.results
      .map(change => change.doc)
      .filter(doc => doc && doc.form === 'delivery');
    return { ...state, data: { reports } };
  }
);

