mpesa.code:
// Prompt a member to pay their monthly health insurance contribution.
// BusinessShortCode, Password and Timestamp are added for you from the credential.
stkPush({
  Amount: $.data.amount, // KES, whole shillings
  PartyA: $.data.phone, // payer, format 2547XXXXXXXX
  PartyB: $.configuration.short_code, // paybill receiving the funds
  PhoneNumber: $.data.phone, // phone that receives the PIN prompt
  CallBackURL: 'https://app.openfn.org/i/<your-webhook-id>', // receives the result
  AccountReference: $.data.memberNo, // max 12 characters, shown to the payer
  TransactionDesc: 'Monthly contribution',
});

// Register the URLs M-Pesa calls when customers pay into your paybill.
registerUrl({
  ShortCode: $.configuration.short_code,
  ResponseType: 'Completed', // what to do if the validation URL is unreachable
  ConfirmationURL: 'https://app.openfn.org/i/<confirmation-webhook-id>',
  ValidationURL: 'https://app.openfn.org/i/<validation-webhook-id>',
});

// Pay a pharmacy supplier's till for a medicines order.
buyGoods({
  Initiator: $.configuration.initiatorName, // API operator username
  SecurityCredential: $.configuration.securityCredential, // encrypted operator password
  Amount: $.data.amount,
  PartyA: $.configuration.short_code, // your shortcode (money leaves here)
  PartyB: $.data.supplierTill, // supplier's till number
  AccountReference: $.data.orderNo, // up to 13 characters
  Requester: $.data.requesterPhone, // optional, 2547XXXXXXXX
  Remarks: 'Medicines order payment',
  QueueTimeOutURL: 'https://app.openfn.org/i/<timeout-webhook-id>',
  ResultURL: 'https://app.openfn.org/i/<result-webhook-id>',
});

// Remit tax to KRA using a payment registration number (PRN).
remitTax({
  Initiator: $.configuration.initiatorName,
  SecurityCredential: $.configuration.securityCredential,
  Amount: $.data.taxAmount,
  PartyA: $.configuration.short_code,
  AccountReference: $.data.prn, // PRN issued by KRA
  Remarks: 'Monthly PAYE remittance',
  QueueTimeOutURL: 'https://app.openfn.org/i/<timeout-webhook-id>',
  ResultURL: 'https://app.openfn.org/i/<result-webhook-id>',
});

// Send an STK push to each member in the incoming list.
each(
  $.data.members,
  stkPush({
    Amount: $.data.amount,
    PartyA: $.data.phone,
    PartyB: $.configuration.short_code,
    PhoneNumber: $.data.phone,
    CallBackURL: 'https://app.openfn.org/i/<your-webhook-id>',
    AccountReference: $.data.memberNo,
    TransactionDesc: 'Savings group contribution',
  })
);

// Call a Daraja endpoint directly. Paths are relative to the baseUrl.
request(
  // 1) HTTP method.
  'POST',
  // 2) Daraja path.
  '/mpesa/c2b/v1/registerurl',
  // 3) JSON body.
  {
    ShortCode: $.configuration.short_code,
    ResponseType: 'Completed',
    ConfirmationURL: 'https://app.openfn.org/i/<confirmation-webhook-id>',
    ValidationURL: 'https://app.openfn.org/i/<validation-webhook-id>',
  }
);

// Check whether a payment went through. The result is sent to ResultURL.
checkTransactionStatus({
  Initiator: $.configuration.initiatorName,
  SecurityCredential: $.configuration.securityCredential,
  TransactionID: $.data.mpesaReceipt, // e.g. 'OEI2AK4Q16'
  PartyA: $.configuration.short_code,
  IdentifierType: 4, // 4 = organisation shortcode
  ResultURL: 'https://app.openfn.org/i/<result-webhook-id>',
  QueueTimeOutURL: 'https://app.openfn.org/i/<timeout-webhook-id>',
  Remarks: 'Reconciliation check',
  Occassion: 'Monthly reconciliation', // note Daraja's spelling
});

