  // 1) The owning organization (or user) id.
  'MSFOCG',
  // 2) The collection (or source) id.
  $.data.collectionId,
  // 3) Options: owner/repository type, version and query params.
  {
    ownerType: 'orgs', // 'orgs' or 'users'
    repository: 'collections', // 'collections' or 'sources'
    version: 'HEAD', // or a released version, e.g. 'v1.2'
    page: 1,
    limit: 200,
    verbose: false,
  }
);

// Search concepts in a source, e.g. CIEL, by free-text keyword.
get(
  // 1) Path relative to the OCL host URL.
  'orgs/CIEL/sources/CIEL/concepts/',
  // 2) Query parameters.
  {
    q: 'malaria', // free-text search
    limit: 25,
    page: 1,
    verbose: true, // include names and descriptions
    includeRetired: false,
  }
);

// Fetch one concept (names, datatype, class) from a source.
get(
  // 1) orgs/{org}/sources/{source}/concepts/{concept}/
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/`,
  // 2) Query parameters.
  { verbose: true }
);

// List the mappings that start from one concept, e.g. CIEL -> ICD-10.
get(
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/mappings/`,
  {
    limit: 100,
    includeRetired: false,
  }
);

// Pull only the concepts changed since the last sync.
get(
  `orgs/${$.data.orgId}/sources/${$.data.sourceId}/concepts/`,
  {
    // ISO date of the last successful sync (e.g. saved in state or a collection).
    updatedSince: $.data.lastSync || '2026-01-01',
    limit: 200,
    page: 1,
    verbose: true,
  }
);

// Get a concept plus everything it links to (answers, set members).
get(
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/$cascade/`,
  {
    cascadeHierarchy: true, // follow parent/child links
    cascadeMappings: true, // follow mappings
    cascadeLevels: 1, // how many levels deep
    mapTypes: 'Q-AND-A,CONCEPT-SET', // only these map types
  }
);

// List the released versions of a source.
get(
  `orgs/${$.data.orgId}/sources/${$.data.sourceId}/versions/`,
  { limit: 20 }
);

// List the concepts in a released collection version (e.g. a facility form value set).
get(
  // orgs/{org}/collections/{collection}/{version}/concepts/
  `orgs/${$.data.orgId}/collections/${$.data.collectionId}/v1.0/concepts/`,
  {
    limit: 100,
    page: 1,
    verbose: true,
  }
);

// List the sources (terminologies) an organization publishes.
get(
  `orgs/${$.data.orgId}/sources/`,
  { limit: 50 }
);

odk.code:
// Create an Entity so it shows up as a case in follow-up forms.
post(
  // 1) Dataset (entity list) path.
  `v1/projects/${$.data.projectId}/datasets/households/entities`,
  // 2) Entity body: uuid, label and dataset property values (strings).
  {
    uuid: $.data.householdUuid,
    label: `${$.data.headOfHousehold} (${$.data.village})`,
    data: {
      head_name: $.data.headOfHousehold,
      village: $.data.village,
      members: String($.data.memberCount),
    },
  }
);

// Create many Entities at once from an upstream list.
post(
  // 1) Dataset (entity list) path.
  `v1/projects/${$.data.projectId}/datasets/patients/entities`,
  // 2) Bulk body: entities plus a source describing where they came from.
  {
    entities: $.data.patients.map(p => ({
      uuid: p.uuid,
      label: `${p.name} (${p.age})`,
      data: { name: p.name, age: String(p.age), facility: p.facility },
    })),
    source: { name: 'emr-export.json', size: $.data.patients.length },
  }
);

// Update properties on an existing Entity.
request(
  // 1) HTTP method.
  'PATCH',
  // 2) Entity path.
  `v1/projects/${$.data.projectId}/datasets/patients/entities/${$.data.uuid}`,
  // 3) Fields to change.
  {
    data: { status: 'referred', referral_facility: $.data.facility },
  },
  // 4) force=true skips the baseVersion conflict check.
  { query: { force: true } }
);

// Mark a submission as approved once it has been synced.
request(
  // 1) HTTP method.
  'PATCH',
  // 2) Submission path.
  `v1/projects/${$.data.projectId}/forms/patient-follow-up/submissions/${$.data.__id}`,
  // 3) New review state: approved, hasIssues, rejected or edited.
  { reviewState: 'approved' }
);

// Leave a comment on a submission for data managers.
post(
  // 1) Submission comments path.
  `v1/projects/${$.data.projectId}/forms/patient-follow-up/submissions/${$.data.__id}/comments`,
  // 2) Comment body.
  { body: 'Could not match this patient ID in the EMR. Please check.' }
);

// Create an App User for a new enumerator.
post(`v1/projects/${$.data.projectId}/app-users`, {
  displayName: $.data.enumeratorName, // e.g. 'CHW - Kisumu East 04'
});

// Fetch submissions received since the last run.
getSubmissions(
  // 1) Project id.
  $.data.projectId,
  // 2) Form id (xmlFormId).
  'patient-follow-up',
  // 3) OData query: only submissions after a date, e.g. 2026-10-01T00:00:00.000Z.
  {
    $filter: `$root/Submissions/__system/submissionDate gt ${$.data.since}`,
  }
);

// List Entities (cases) in a dataset via OData.
get(`v1/projects/${$.data.projectId}/datasets/patients.svc/Entities`, {
  query: {
    // OData filter on entity properties or system fields.
    $filter: "status eq 'active'",
    $top: 250,
  },
});

