// Create a birth event and send the declaration in one call.
submitBirthNotification(
  // 1) Flat, dotted-key declaration.
  {
    'child.name': { firstname: $.data.childFirstName, surname: $.data.childSurname },
    'child.dob': $.data.dateOfBirth,
    'child.gender': $.data.sex, // 'male' | 'female'
    'child.placeOfBirth': 'HEALTH_FACILITY',
    'child.birthLocation': $.data.facilityLocationId,
    'informant.relation': 'MOTHER',
  },
  // 2) Options: the location the notification is made from.
  { createdAtLocation: $.data.facilityLocationId }
);

// Create a death event at a known location. The new event id is on state.data.id.
createEvent('death', {
  createdAtLocation: $.data.facilityLocationId,
});

// Send declaration data for an existing event (e.g. from createEvent).
notifyEvent(
  // 1) Event id from the previous step.
  $.data.id,
  // 2) Flat, dotted-key declaration.
  {
    'child.name': { firstname: 'Amina', surname: 'Okello' },
    'child.dob': '2026-10-28',
    'child.gender': 'female',
  },
  // 3) Options.
  { createdAtLocation: $.configuration.facilityLocationId }
);

// Submit a FHIR birth notification for v1 gateway deployments.
// Build the entries upstream, e.g. with createDocumentEntry() and fhir-4 builders.
createBirthNotification($.data.bundleEntries);

// Search registered births (v1 GraphQL advanced search).
queryEvents(
