  {
    event: 'birth',
    registrationStatuses: ['REGISTERED'],
    dateOfRegistrationStart: '2026-10-01T00:00:00.000Z',
    dateOfRegistrationEnd: '2026-10-31T23:59:59.999Z',
  },
  // 2) Paging: count defaults to 10.
  { count: 50, skip: 0 }
);

// Search registered deaths at a given location.
queryEvents(
