  patient: $.data.patientUuid,
  // UUID of the encounter type.
  encounterType: $.data.encounterTypeUuid,
  location: $.data.locationUuid,
  encounterDatetime: $.data.visitDate,
  obs: [
    {
      // Concept UUID for weight (kg).
      concept: $.data.weightConceptUuid,
      value: $.data.weightKg,
    },
    {
      // Concept UUID for systolic blood pressure.
      concept: $.data.systolicConceptUuid,
      value: $.data.systolic,
    },
  ],
});

// Save a single observation, e.g. a viral load result.
create('obs', {
  // UUID of the patient (as a person).
  person: $.data.patientUuid,
  // Concept UUID of the measured value.
  concept: $.data.conceptUuid,
  obsDatetime: $.data.resultDate,
  value: $.data.result,
  // Optional: link to an existing encounter.
  encounter: $.data.encounterUuid,
  comment: 'Imported from the lab information system',
});

// Add an identifier sub-resource to an existing patient.
create(`patient/${$.data.patientUuid}/identifier`, {
  identifier: $.data.nationalId,
  // UUID of the identifier type (e.g. National ID).
  identifierType: $.data.identifierTypeUuid,
  location: $.data.locationUuid,
  preferred: false,
});

// Record an allergy for a patient.
create(`patient/${$.data.patientUuid}/allergy`, {
  allergen: {
    allergenType: 'DRUG',
    // Concept UUID of the allergen (e.g. Penicillin).
    codedAllergen: { uuid: $.data.allergenConceptUuid },
  },
  // Concept UUID of the severity (e.g. Moderate).
  severity: { uuid: $.data.severityConceptUuid },
  comment: 'Reported by patient at intake',
});

// Update a person's demographics.
update(
  // 1) Path to the person, including its UUID.
  `person/${$.data.personUuid}`,
  // 2) Only the fields to change.
  {
    birthdate: $.data.birthdate,
    gender: $.data.gender,
  }
);

// Void an encounter entered in error.
destroy(
  // 1) Path to the encounter, including its UUID.
  `encounter/${$.data.encounterUuid}`,
  // 2) Set purge: true to delete permanently instead of voiding.
  { purge: false }
);

// Search patients by name or identifier.
get('patient', {
  // Maps to OpenMRS's `q` parameter.
  query: $.data.patientId,
  // Representation: default, full or ref.
  v: 'default',
  // Stop after this many results (pagination is automatic).
  max: 50,
});

// Fetch one patient by UUID.
get(`patient/${$.data.patientUuid}`, {
  v: 'full',
  // Return the object rather than an array of one.
  singleton: true,
});

// List encounters for a patient.
get('encounter', {
  patient: $.data.patientUuid,
  // Optional: only one encounter type.
  encounterType: $.data.encounterTypeUuid,
  fromdate: '2026-01-01',
  v: 'default',
});

// Fetch a patient's observations for a single concept.
get('obs', {
  patient: $.data.patientUuid,
  concept: $.data.conceptUuid,
  v: 'full',
});

// List locations matching a name.
get('location', {
  query: 'Clinic',
  v: 'default',
});

// Look up concepts by name, e.g. to resolve concept UUIDs.
get('concept', {
  query: 'malaria',
  // Results in French where translations exist.
  language: 'fr',
  limit: 25,
});

openspp.code:
