pdfshift.code:
// Render a patient referral letter as a PDF.
// state.data will hold the PDF as a base64 string.
generatePDF(
  // 1) HTML string (or a URL) to convert.
  `<html>
  <body>
    <h1>Referral Letter</h1>
    <p>Patient: ${$.data.patientName}</p>
    <p>Referred to: ${$.data.referralFacility}</p>
    <p>Reason: ${$.data.reason}</p>
  </body>
</html>`,
  // 2) Optional PDFShift options.
  { format: 'A4' }
);

// Convert a hosted report page to PDF and get a temporary S3 link.
generatePDF($.data.reportUrl, {
  // With a filename, PDFShift returns JSON with a download url (kept 2 days).
  filename: `monthly-report-${$.data.month}`,
  format: 'A4',
  landscape: true,
});

// Test a vaccination certificate layout without spending credits.
generatePDF(
  `<html><body style="text-align:center">
    <h1>Certificate of Vaccination</h1>
    <h2>${$.data.fullName}</h2>
    <p>${$.data.vaccine}, dose ${$.data.doseNumber}, given ${$.data.dateGiven}</p>
  </body></html>`,
  {
    sandbox: true, // watermarked output, free, max 10 docs/minute
