);

// Generate a beneficiary statement with header and page numbers.
generatePDF($.data.statementHtml, {
  format: 'A4',
  margin: '20mm',
  header: {
    source: '<div style="font-size:10px">Cash Transfer Programme Statement</div>',
  },
