  },
});

// Render an HTML summary card as a PNG image.
request(
  // 1) HTTP method.
  'POST',
  // 2) Path relative to the PDFShift API base URL.
  '/convert/png',
  // 3) Request body.
  { source: $.data.summaryHtml }
);

// Check credit usage before a large batch run.
request(
  'GET',
  '/credits/usage',
  {}, // no body needed
  { parseAs: 'json' }
);

// List recent failed conversions to debug a job.
request('GET', '/logs', {}, {
  query: { status: 'error', limit: 20 },
  parseAs: 'json',
});

