postgresql.code:
// Insert one row into a table.
// The new row is returned on state.data.
insert(
  // Target table name.
  'users',
  // The record as a plain object (column => value).
  { name: 'Elodie', email: 'elodie@example.org', age: 31 },
  // Optional settings.
  {
    // Print the generated SQL to the run log (handy while developing).
    writeSql: true,
    // Treat these literal strings in the payload as SQL NULL.
    setNull: ["''", "'undefined'"],
  }
);

// Update an existing row using a parameterised SQL statement.
// $1, $2... are bound from the `values` array (safe against SQL injection).
sql(
  'UPDATE users SET email = $1, updated_at = NOW() WHERE id = $2;',
  {
    values: [$.data.email, $.data.id],
    writeSql: true,
  }
);

// Fetch a single row's value from a relation.
// Result is written to state.data.
findValue({
  // The column to return (or 'id' / uuid column).
  uuid: 'id',
  // The table or view to query.
  relation: 'users',
  // Equality filter (combined with AND).
  where: { email: $.data.email },
  // Optional operator override per column.
  operator: { email: '=' },
});

// Run an arbitrary SELECT. Results are on state.data.rows.
sql(
  'SELECT * FROM users WHERE email = $1 LIMIT 1;',
  {
    values: [$.data.email],
    writeSql: true,
  }
);

// Run an arbitrary SELECT returning many rows.
sql(
  'SELECT id, name, email FROM users WHERE created_at > $1 ORDER BY id;',
  {
    values: ['2026-01-01'],
  }
);

primero.code:
// Create a new case in Primero from an intake submission.
createCase({
  data: {
    name_first: $.data.firstName,
    name_last: $.data.lastName,
    sex: $.data.sex, // e.g. 'female'
    date_of_birth: $.data.dateOfBirth, // 'YYYY-MM-DD'
    registration_date: $.data.registrationDate,
    protection_concerns: ['unaccompanied', 'separated'],
    status: 'open',
  },
});

// Create or update a case, matching on case_id to avoid duplicates.
upsertCase({
  // Case attribute(s) used to look up an existing record.
  externalIds: ['case_id'],
  data: {
    case_id: $.data.caseId,
    name_first: $.data.firstName,
    name_last: $.data.lastName,
    sex: $.data.sex,
    age: $.data.age,
    status: 'open',
  },
});

// Update an existing case, e.g. after a follow-up visit.
updateCase(
  // 1) Primero record id (uuid) of the case.
  $.data.recordId,
  // 2) Fields to change.
  {
    data: {
      risk_level: 'high',
      protection_concerns: ['physical_violence'],
    },
  }
);

// Refer cases to a service provider's user in bulk.
createReferrals({
  data: {
    // Primero record ids of the cases to refer.
    ids: $.data.caseRecordIds,
    // user_name of the receiving user.
    transitioned_to: $.data.receivingUserName,
    notes: 'Referred for psychosocial support services',
  },
});

// Mark a referral as done once the partner agency has delivered the service.
updateReferral({
  // Match the case by its Primero record id.
  caseExternalId: 'record_id',
  // Case record id.
  caseId: $.data.caseRecordId,
  // Referral id.
  id: $.data.referralId,
  data: {
    status: 'done',
    notes: 'Service delivered by partner agency',
  },
});

// Get cases flagged for remote access, filtered by sex and age range.
getCases({
  remote: true,
  sex: 'female',
  age: '10..17',
  per: 100,
  page: 1,
});

// Look up one case by its case_id.
getCases({
  case_id: $.data.caseId,
});

// Get remote cases along with their referrals (one extra request per case).
getCases(
  // 1) Query parameters.
  { remote: true },
  // 2) Options.
  { withReferrals: true }
);

// Get the referrals made on a case, matched by its Primero record id.
getReferrals({
  externalId: 'record_id',
  id: $.data.caseRecordId,
});

// Fetch lookups to translate option ids into display values.
getLookups({
  per: 1000,
  page: 1,
});

// Fetch locations, e.g. to map Primero location codes to another system.
getLocations({
  page: 1,
  per: 500,
});

// Get the form sections configured for a module.
getForms({
  module_id: $.data.moduleId,
});

progres.code:
