    status: 'Delivery Fail',
    closure_reason: 'Referral is missing required fields. Please complete and re-send.',
  },
  headers: { 'Ocp-Apim-Subscription-Key': $.configuration.token },
  agentOptions: { key: $.configuration.key, cert: $.configuration.cert },
});

