rapidpro.code:
// Create or update a contact using their phone number as the key.
upsertContact({
  name: $.data.fullName,
  // ISO 639-3 language code.
  language: 'eng',
  // The first URN is used to find an existing contact.
  urns: [`tel:${$.data.phoneNumber}`],
  // Custom contact fields (keys must already exist in the workspace).
  fields: {
    facility: $.data.facilityName,
    expected_delivery_date: $.data.edd,
  },
});

// Register a new caregiver and add them to the reminders group.
addContact({
  name: $.data.caregiverName,
  language: 'fra',
  urns: [`tel:${$.data.phoneNumber}`],
  // Group UUIDs from your RapidPro workspace.
  groups: [$.data.remindersGroupUuid],
  fields: {
    child_dob: $.data.childDateOfBirth,
    district: $.data.district,
  },
});

// Enrol a patient into the antenatal care reminder flow.
startFlow({
  // Flow UUID from RapidPro.
  flow: $.configuration.ancFlowUuid,
  // Contact UUIDs, e.g. from an earlier upsertContact().
  contacts: [$.data.uuid],
  // Don't restart people who have already been through this flow.
  restart_participants: false,
});

// Start a payment confirmation survey for a list of recipients.
startFlow({
  flow: $.configuration.surveyFlowUuid,
  // URNs work even if the contact doesn't exist yet.
  urns: $.data.recipients.map(r => `tel:${r.phone}`),
  // Skip contacts that are already active in another flow.
  exclude_active: true,
  // Available in the flow as @trigger.params.
  params: { payment_cycle: $.data.cycle, amount: $.data.amount },
});

// Start the monthly check-in flow for all community health workers.
startFlow({
  flow: $.configuration.checkInFlowUuid,
  groups: [$.data.chwGroupUuid],
  restart_participants: true,
});

// Send an appointment reminder.
sendBroadcast({
  text: `Hello ${$.data.firstName}, your clinic visit is on ${$.data.appointmentDate}.`,
  urns: [`tel:${$.data.phoneNumber}`],
});

// Alert all contacts in a district group about a vaccination campaign.
sendBroadcast({
  text: 'Free measles vaccination this Saturday at your nearest health centre.',
  groups: [$.data.districtGroupUuid],
});

// Sync a list of beneficiaries into RapidPro contacts.
each(
  $.data.beneficiaries,
  // Inside each(), $.data is the current beneficiary.
  upsertContact({
    name: $.data.name,
    urns: [`tel:${$.data.phone}`],
    fields: { household_id: $.data.householdId },
  })
);

redis.code:
// Remember when this sync ran so the next run can pick up from here.
set(
  // 1) Key.
  'sync:dhis2:lastRun',
  // 2) String value.
  new Date().toISOString()
);

// Cache a patient's key fields as a Redis hash.
hset(
  // 1) Key, namespaced by record type and id.
  `patient:${$.data.patientId}`,
  // 2) Field/value pairs.
  {
    name: $.data.name,
    facility: $.data.facilityCode,
    ihs_number: $.data.ihsNumber,
  }
);

// Save a full JSON document under one key (requires RedisJSON).
jSet(
  // 1) Key.
  `beneficiary:${$.data.beneficiaryId}`,
  // 2) Object to store at the root path.
  {
    name: $.data.name,
    household: $.data.householdId,
    enrolledOn: $.data.enrolledOn,
    status: 'active',
  }
);

// Save a batch of records as JSON documents in one call.
mSet(
  $.data.records.map(record => ({
    key: `facility:${record.code}`,
    value: record, // object or string
  }))
);

// Read one field from a patient hash.
hget(
  // 1) Key.
  `patient:${$.data.patientId}`,
  // 2) Field name.
  'ihs_number'
);

// Read several JSON documents in one call.
mGet(
  $.data.facilityCodes.map(code => `facility:${code}`)
);

// Find all cached patient hashes; state.data becomes an array of keys.
scan('patient:*', {
  type: 'hash', // 'string' | 'hash' | 'json' ...
  count: 500, // keys fetched per scan iteration
});

