// Run a SOSL text search across several objects.
fn(async state => {
  const sosl = `FIND {${state.data.searchTerm}} IN ALL FIELDS RETURNING Contact(Id, Name, Email), Account(Id, Name)`;
  const result = await sfRequest({
    method: 'GET',
    url: `/services/data/v59.0/search?q=${encodeURIComponent(sosl)}`,
  });
  // result.searchRecords holds the matches.
  return { ...state, data: result };
});

// Find child Contacts for a given Account using SOQL.
query(
  `SELECT Id, Name FROM Contact WHERE AccountId = '${$.data.accountId}'`
);

// Find one record by a couple of fields.
query(
  `SELECT Id, Name FROM Account WHERE Name = '${$.data.name}' AND Industry = '${$.data.industry}' LIMIT 1`
);

// Find a record using a SOQL WHERE clause you control.
query(
  `SELECT Id, Name FROM Account WHERE ${$.data.whereClause} LIMIT 1`
);

// Find many records by a single field/value match.
query(
  `SELECT Id, Name, Email FROM Contact WHERE AccountId = '${$.data.accountId}' LIMIT 200`
);

// Find many records using a SOQL WHERE clause you control.
query(
  `SELECT Id, Name FROM Account WHERE ${$.data.whereClause} LIMIT 200`
);

// Pull ContentDocumentLink rows for a record to enumerate attached files.
query(
  `SELECT ContentDocumentId, ContentDocument.Title, ContentDocument.FileType ` +
  `FROM ContentDocumentLink WHERE LinkedEntityId = '${$.data.recordId}'`
);

satusehat.code:
// Create an outpatient Encounter for a patient visit.
// Path is relative to the credential's baseUrl (…/fhir-r4/v1).
post('Encounter', {
  resourceType: 'Encounter',
  identifier: [
    {
      // Your organization's local encounter id.
      system: `http://sys-ids.kemkes.go.id/encounter/${$.configuration.organizationId}`,
      value: $.data.visitId,
    },
  ],
  status: 'arrived',
  class: {
    system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
    code: 'AMB',
    display: 'ambulatory',
  },
  subject: { reference: `Patient/${$.data.patientIhsId}`, display: $.data.patientName },
  participant: [
    { individual: { reference: `Practitioner/${$.data.practitionerIhsId}` } },
  ],
  period: { start: $.data.arrivedAt },
  location: [{ location: { reference: `Location/${$.data.locationId}` } }],
  serviceProvider: { reference: `Organization/${$.configuration.organizationId}` },
});

// Record a body temperature Observation for an encounter.
post('Observation', {
  resourceType: 'Observation',
  status: 'final',
  category: [
    {
      coding: [
        {
          system: 'http://terminology.hl7.org/CodeSystem/observation-category',
          code: 'vital-signs',
        },
      ],
    },
  ],
  code: {
    coding: [{ system: 'http://loinc.org', code: '8310-5', display: 'Body temperature' }],
  },
  subject: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  effectiveDateTime: $.data.measuredAt,
  valueQuantity: {
    value: $.data.temperature,
    unit: 'C',
    system: 'http://unitsofmeasure.org',
    code: 'Cel',
  },
});

// Record an ICD-10 diagnosis for an encounter.
post('Condition', {
  resourceType: 'Condition',
  clinicalStatus: {
    coding: [
      {
        system: 'http://terminology.hl7.org/CodeSystem/condition-clinical',
        code: 'active',
      },
    ],
  },
  category: [
    {
      coding: [
        {
          system: 'http://terminology.hl7.org/CodeSystem/condition-category',
          code: 'encounter-diagnosis',
        },
      ],
    },
  ],
  code: {
    coding: [{ system: 'http://hl7.org/fhir/sid/icd-10', code: 'A09', display: 'Diarrhoea and gastroenteritis' }],
  },
  subject: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
});

// Report a vaccination given at the facility.
post('Immunization', {
  resourceType: 'Immunization',
  status: 'completed',
  vaccineCode: {
    coding: [{ system: 'http://sys-ids.kemkes.go.id/kfa', code: $.data.kfaCode, display: $.data.vaccineName }],
  },
  patient: { reference: `Patient/${$.data.patientIhsId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  occurrenceDateTime: $.data.givenAt,
  lotNumber: $.data.lotNumber,
  performer: [{ actor: { reference: `Practitioner/${$.data.practitionerIhsId}` } }],
  protocolApplied: [{ doseNumberPositiveInt: $.data.doseNumber }],
});

// Mark an encounter as finished using a JSON Patch.
patch(
  // 1) Resource type and id.
  `Encounter/${$.data.encounterId}`,
  // 2) JSON Patch operations.
  [
    { op: 'replace', path: '/status', value: 'finished' },
    { op: 'add', path: '/period/end', value: $.data.dischargedAt },
  ]
);

// Register a clinic room as a Location under your organization.
post('Location', {
  resourceType: 'Location',
  identifier: [
    {
      system: `http://sys-ids.kemkes.go.id/location/${$.configuration.organizationId}`,
      value: $.data.roomCode,
    },
  ],
  status: 'active',
  name: $.data.roomName, // e.g. 'Poli Umum'
  mode: 'instance',
  physicalType: {
    coding: [{ system: 'http://terminology.hl7.org/CodeSystem/location-physical-type', code: 'ro', display: 'Room' }],
  },
  managingOrganization: { reference: `Organization/${$.configuration.organizationId}` },
});

// Find a patient by national identity number (NIK).
get('Patient', {
  identifier: `https://fhir.kemkes.go.id/id/nik|${$.data.nik}`,
});

// Find a practitioner by NIK to get their IHS number.
get('Practitioner', {
  identifier: `https://fhir.kemkes.go.id/id/nik|${$.data.practitionerNik}`,
});

// List a patient's encounters.
get('Encounter', {
  subject: $.data.patientIhsId, // the patient's IHS id
  _count: 50,
});

// List observations recorded in one encounter.
get('Observation', {
  encounter: $.data.encounterId,
  _count: 100,
});

senaite.code:
// Create a sample (AnalysisRequest) inside a client, e.g. from an OpenMRS lab order.
// Paths are relative to the credential's baseUrl (…/@@API/senaite/v1).
request(
  // 1) HTTP method.
  'POST',
  // 2) Create an AnalysisRequest in the client folder with this UID.
  `AnalysisRequest/create/${$.data.clientUid}`,
  // 3) Options: the sample fields go in the body.
  {
    body: {
      Contact: $.data.contactUid,
      SampleType: $.data.sampleTypeUid,
      DateSampled: $.data.collectedAt,
      ClientSampleID: $.data.orderNumber,
      // UIDs of the AnalysisServices to run.
      Analyses: $.data.testUids,
    },
  }
);

// Create a Client (e.g. a referring health facility).
request('POST', 'Client/create', {
  body: {
    title: $.data.facilityName,
    ClientID: $.data.facilityCode,
    parent_path: '/senaite/clients',
  },
});

// Update a sample and run a workflow transition on it.
request('POST', `AnalysisRequest/update/${$.data.sampleUid}`, {
  body: {
    // Workflow transition to run after the update.
    transition: 'receive',
    Remarks: 'Received via courier from district hospital',
  },
});

// Update fields on any object (portal type inferred from the UID).
request('POST', `update/${$.data.uid}`, {
  body: {
    Phone: $.data.phone,
    EmailAddress: $.data.email,
  },
});

// Find samples published recently, returning full object data.
request('GET', 'search', {
  query: {
    portal_type: 'AnalysisRequest',
    catalog: 'senaite_catalog_sample',
    review_state: 'published',
    modified_since: '2d',
    complete: 'yes',
    limit: 100,
  },
});

// Find a sample by the client's own sample/order id.
request('GET', 'AnalysisRequest', {
  query: {
    getClientSampleID: $.data.orderNumber,
    catalog: 'senaite_catalog_sample',
    complete: 'yes',
  },
});

// List active analysis services.
request('GET', 'AnalysisService', {
  query: { review_state: 'active', complete: 'yes', limit: 200 },
});

sftp.code:
// Upload a local file to the SFTP server.
putCSV(
  // 1) Path of the file on the worker's local disk.
  '/tmp/monthly_distributions.csv',
  // 2) Destination path on the SFTP server.
  `/inbound/distributions_${new Date().toISOString().slice(0, 10)}.csv`
);

// Download a CSV from the SFTP server; rows are parsed to JSON on state.data.
// For JSON files use getJSON('/outbound/file.json', 'utf8') instead.
getCSV(
  // 1) Remote file path.
  '/outbound/beneficiaries.csv',
  // 2) Parsing options (csv-parse).
  { delimiter: ',' }
);

