// Cancel a subscription immediately.
// The adaptor's own helpers are read-only, so this calls the Stripe API
// with util.request. Stripe expects form-encoded bodies, not JSON.
fn(async state => {
  const { baseUrl = 'https://api.stripe.com', apiVersion = 'v1', apiKey } = state.configuration;
  const form = params => Object.entries(params)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');

  const response = await util.request('DELETE', `${baseUrl}/${apiVersion}/subscriptions/${state.data.subscriptionId}`, {
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'content-type': 'application/x-www-form-urlencoded',
    },
    body: form({
      // Optional: generate a final invoice for any un-invoiced usage.
      invoice_now: false,
    }),
    parseAs: 'json',
  });

  return { ...state, data: response.body };
});

