sunbird-rc.code:
// Issue a vaccination certificate as a Verifiable Credential.
issueCredential({
  credential: {
    '@context': ['https://www.w3.org/2018/credentials/v1'],
    type: ['VerifiableCredential', 'VaccinationCertificate'],
    // DID of the issuing health authority.
    issuer: $.data.issuerDid,
    issuanceDate: new Date().toISOString(),
    credentialSubject: {
      id: $.data.recipientDid,
      name: $.data.patientName,
      vaccine: $.data.vaccine, // e.g. 'Measles-Rubella'
      dose: $.data.doseNumber,
      dateOfVaccination: $.data.vaccinationDate,
      facility: $.data.facilityName,
    },
  },
  // Credential schema registered in the credential-schema service.
  credentialSchemaId: $.data.schemaId,
  credentialSchemaVersion: '1.0.0',
  tags: ['immunization'],
});

// Issue a programme-enrolment credential to a beneficiary.
issueCredential({
  credential: {
    '@context': ['https://www.w3.org/2018/credentials/v1'],
    type: ['VerifiableCredential', 'BenefitEligibilityCredential'],
    issuer: $.data.issuerDid,
    issuanceDate: new Date().toISOString(),
    expirationDate: $.data.validUntil,
    credentialSubject: {
      id: $.data.beneficiaryDid,
      name: $.data.beneficiaryName,
      programme: $.data.programmeName, // e.g. 'Child Support Grant'
      householdId: $.data.householdId,
    },
  },
  credentialSchemaId: $.data.schemaId,
  credentialSchemaVersion: '1.0.0',
  tags: ['social-protection'],
});

// Download a credential rendered with a template.
downloadCredential(
  // 1) Credential id.
  $.data.credentialId,
  // 2) Template used to render it.
  { templateId: $.data.templateId }
);

// Find all credentials issued to one person.
post('credentials/search', {
  subject: { id: $.data.recipientDid },
  issuer: { id: $.data.issuerDid },
});

surveycto.code:
// Create or update one record in a server dataset
// (e.g. a case list used to pre-load follow-up forms).
upsertRecord(
  // 1) The dataset id.
  'household_roster',
  // 2) The record. `id` is the unique key for the upsert.
  {
    id: $.data.householdId,
    head_of_household: $.data.headName,
    village: $.data.village,
    enrolled_on: $.data.enrollmentDate,
  }
);

// Upload many rows to a dataset in one call (sent as CSV).
uploadCsvRecords(
  // 1) The dataset id.
  'health_facilities',
  // 2) Rows to upload, e.g. a facility list pulled from DHIS2.
  $.data.facilities.map(f => ({
    id: f.code,
    name: f.name,
    district: f.district,
  })),
  // 3) Upload options: MERGE keeps existing rows and updates by key.
  { uploadMode: 'MERGE', joiningField: 'id' }
);

// Create (or update) a server dataset.
upsertDataset({
  id: 'enumerators',
  title: 'Enumerators',
  discriminator: 'ENUMERATORS', // or DATA
  locationContext: {
    parentGroupId: 1, // the form group the dataset sits in
  },
  allowOfflineUpdates: false,
  idFormatOptions: {
    prefix: 'enum',
    suffix: '',
    numberOfDigits: '6',
    allowCapitalLetters: false,
  },
});

// Start from the cursor saved on the last run, or from today on the first run.
cursor($.cursor, { defaultValue: 'today' });

// Fetch submissions for a form since the cursor (JSON, wide format).
fetchSubmissions('household_survey', { date: $.cursor });

// Move the cursor forward for the next run.
cursor('now');

// Fetch reviewed submissions only.
fetchSubmissions('anc_visit', {
  // Review status: approved, rejected, pending, or combined e.g. 'approved|pending'.
  status: 'approved',
  // Optional: only submissions since this date (ISO dates are converted for you).
  date: '2026-01-01T00:00:00Z',
});

// List the records in a dataset.
list(`datasets/${$.data.datasetId}/records`, {
  limit: 1000, // page size, max 1000
});

