twilio.code:
// Not supported: this adaptor only exposes sendSMS(), so it can't place
// voice calls, and it has no generic request helper.
// Closest option: send the message as an SMS to each number instead.
each(
  $.data.phoneNumbers,
  sendSMS({
    body: 'Reminder: your clinic appointment is tomorrow at 9am.',
    from: $.configuration.fromNumber,
    // Each item is an E.164 number, e.g. +14155551212.
    to: $.data,
  })
);

// Send an SMS via Twilio.
// state.references is populated with Twilio's API response.
sendSMS({
  // Message body (max 1600 chars, billed per 160-char segment).
  body: `Hi ${$.data.name}, your appointment is confirmed.`,
  // Your Twilio sending number, in E.164 format (e.g. +14155551212).
  from: $.configuration.fromNumber,
  // Recipient, in E.164 format.
  to: $.data.phone,
});

// Send a WhatsApp message to each recipient.
// sendSMS() uses Twilio's Messages API, which delivers over WhatsApp when
// both numbers have the whatsapp: prefix.
each(
  $.data.recipients,
  sendSMS({
    body: `Hi ${$.data.name}, your test results are ready to collect.`,
    // Your WhatsApp-enabled Twilio sender, in E.164 format.
    from: `whatsapp:${$.configuration.fromNumber}`,
    to: `whatsapp:${$.data.phone}`,
  })
);

// Not supported: this adaptor has no generic request helper. It only
// exposes sendSMS(), which calls Twilio's Messages API.
// For other Twilio endpoints, use the HTTP adaptor in a separate step with
// your Account SID and Auth Token as basic auth.
sendSMS({
  body: $.data.message,
  from: $.configuration.fromNumber,
  to: $.data.phone,
});

varo.code:
// Convert message contents (e.g. from gmail's getContentsFromMessages)
// into EMS-compliant cold-chain reports. state.data becomes the reports.
convertToEms(
  // Array of { metadata, data } or { metadata, fridgeTag } objects,
  // each part shaped as { filename, content }.
  $.data
);

// Group flat temperature readings into EMS reports (one per device serial).
convertItemsToReports(
  // 1) Flat records, e.g. loaded from a collection.
  $.data, // e.g. [{ ASER: 'BJBC 08 30', ABST: '20241205T004440Z', TVC: 5.0 }, ...]
  // 2) Report type: 'ems' or 'rtmd'.
  'ems'
);

// Convert RTMD records into EMS reports.
convertItemsToReports(
  // 1) RTMD records from the upstream collection.
  $.data,
  // 2) Report type.
  'rtmd'
);

// Turn EMS reports into message parts to email to a Varo inbox.
// state.data becomes [{ subject, body, data: { filename: 'data.json', content } }].
convertReportsToMessageContents(
  // 1) EMS reports, e.g. from convertItemsToReports().
  $.data,
  // 2) Report type, used in the subject line.
  'ems'
);

// Work out which UTC window (and collection key patterns) matches
// yesterday in the facility's time zone.
fn(state => {
  const range = parseUtcForDataRange(
    // 1) IANA time zone of the facility.
    'Africa/Nairobi',
    // 2) Local start date (ISO).
    '2026-11-01',
    // 3) Local end date (ISO).
    '2026-11-02'
  );
  // range.startUtc, range.endUtc, range.collectionKeys (e.g. ['*20261101*', ...])
  state.range = range;
  return state;
});

// Keep only keys like 'device:20261101T101530Z' that fall in the range.
fn(state => {
  const { startUtc, endUtc } = state.range; // from parseUtcForDataRange()
  state.keys = state.data.filter(key =>
    isKeyInRange(
      // 1) Key with a timestamp after the colon.
      key,
      // 2) Inclusive UTC start.
      startUtc,
      // 3) Exclusive UTC end.
      endUtc
    )
  );
  return state;
});

vtiger.code:
// Create a contact (e.g. a donor from a web form).
postElement({
  operation: 'create',
  elementType: 'Contacts', // module name
  element: {
    firstname: $.data.firstName,
    lastname: $.data.lastName, // required
    email: $.data.email,
    mobile: $.data.phone,
    assigned_user_id: $.configuration.assignedUserId, // e.g. '19x1'
  },
});

// Create an organization (Accounts module).
postElement({
  operation: 'create',
  elementType: 'Accounts',
  element: {
    accountname: $.data.organizationName, // required
    email1: $.data.email,
    phone: $.data.phone,
    website: $.data.website,
    industry: 'Non-Profit',
    assigned_user_id: $.configuration.assignedUserId,
  },
});

// Create a lead from an event registration.
postElement({
  operation: 'create',
  elementType: 'Leads',
  element: {
    firstname: $.data.firstName,
    lastname: $.data.lastName, // required
    company: $.data.organization, // required
    email: $.data.email,
    leadsource: 'Web Site',
    leadstatus: 'Not Contacted',
    assigned_user_id: $.configuration.assignedUserId,
  },
});

// Update only some fields on a record. `id` is the webservice id.
postElement({
  operation: 'revise',
  elementType: 'Contacts',
  element: {
    id: $.data.contactId, // e.g. '12x45'
    mobile: $.data.newPhone,
    email: $.data.newEmail,
  },
});

// Replace a contact record. Mandatory fields must be included.
postElement({
  operation: 'update',
  elementType: 'Contacts',
  element: {
    id: $.data.contactId, // e.g. '12x45'
    firstname: $.data.firstName,
    lastname: $.data.lastName,
    email: $.data.email,
    assigned_user_id: $.configuration.assignedUserId,
  },
});

// Create a contact for each person in the payload.
each(
  '$.data.people[*]',
  postElement({
    operation: 'create',
    elementType: 'Contacts',
    element: {
      firstname: $.data.firstName,
      lastname: $.data.lastName,
      email: $.data.email,
      assigned_user_id: $.configuration.assignedUserId,
    },
  })
);

// List accessible modules (Contacts, Accounts, Leads, ...).
// The result is saved to state.response.body.
listTypes();

whatsapp.code:
// Send a freeform text message via the WhatsApp Business API.
// Only allowed within the 24-hour customer-service window.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  to:   $.data.toPhone,        // E.164, no '+' (e.g. '254712345678')
  type: 'text',
  text: { body: $.data.body },
});

// Send a media attachment. `type` is one of image | video | document | audio.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  to:   $.data.toPhone,
  type: 'image',
  image: {
    // Either a public URL...
    link: $.data.imageUrl,
    // ...or `id` referencing a previously uploaded media id.
    caption: $.data.caption,
  },
});

// Send an approved WhatsApp template message.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  to:   $.data.toPhone,
  type: 'template',
  template: {
    name: 'hello_world',
    language: { code: 'en_US' },
    // Template body variables, if your template uses {{1}}, {{2}}, ...
    // components: [{
    //   type: 'body',
    //   parameters: [{ type: 'text', text: $.data.firstName }],
    // }],
  },
});

wigal-sms.code:
// Send a single SMS.
