zata.code:
// Record a sale (e.g. a pharmacy dispensing) and issue a tax receipt.
post('transaction/sale', {
  body: {
    purchaseCode: $.data.purchaseCode,
    paymentMethodID: $.data.paymentMethodId, // see the payment modes lookup
    customerID: $.data.customerId,
    transactionDate: $.data.date, // 'YYYY-MM-DD'
    customerTIN: $.data.customerTin,
    customerName: $.data.customerName,
    customerPhone: $.data.customerPhone,
    note: 'Synced from clinic POS',
    items: $.data.lines.map(line => ({
      productID: line.productId,
      units: line.quantity,
      unitPrice: line.price,
      discountRate: 0,
      batchNumber: line.batch,
    })),
  },
  // Company and branch scope are sent as headers.
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Preview totals and tax for a basket before recording the sale.
post('transaction/calculate', {
  body: {
    paymentMethodID: $.data.paymentMethodId,
    customerID: $.data.customerId,
    transactionDate: $.data.date,
    items: [
      { productID: $.data.productId, units: 2, unitPrice: 1500 },
    ],
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Register a customer.
post('party/new-customer', {
  body: {
    name: $.data.name, // e.g. 'Kigali Community Clinic'
    phone: $.data.phone,
    email: $.data.email,
    tin: $.data.tin, // taxpayer identification number
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Add a product to inventory.
post('product', {
  body: {
    name: $.data.productName, // e.g. 'Paracetamol 500mg x 100'
    productTypeId: $.data.productTypeId, // see the product types lookup
    unitPrice: $.data.price,
    quantity: $.data.openingStock,
    taxRate: 18,
    batchNumber: $.data.batch,
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Write off stock for a product.
put(`product/reduce-quantity/${$.data.productId}`, {
  body: {
    quantity: $.data.quantity,
    description: 'Expired stock removed',
    batchNumber: $.data.batch,
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Record an expense.
post('expense', {
  body: {
    categoryId: $.data.categoryId,
    amount: $.data.amount,
    description: 'Cold chain transport',
    expenseDate: $.data.date,
    supplierTIN: $.data.supplierTin,
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Initiate a debit payment through ZataPay.
post('zatapay/debit-initiate', {
  body: {
    amount: $.data.amount,
    bankCode: $.data.bankCode, // see the supported banks list
    accountNumber: $.data.accountNumber,
    narration: 'Invoice payment',
    reference: $.data.reference, // your unique reference
  },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// List transactions for a company branch.
get('transaction', {
  query: { page: 1, perPage: 50 },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Fetch one transaction.
get(`transaction/${$.data.transactionId}`, {
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// Check a ZataPay payment's status.
get('zatapay/payment-status', {
  query: { reference: $.data.reference },
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

// List products in inventory.
get('product/pos', {
  headers: {
    companyId: $.data.companyId,
    branchId: $.data.branchId,
  },
});

